// A current "Update 1" derived from the baseline, with realistic slippage so
// the Analysis tab (slippage table + S-curve) is populated on first load.
// Steel frame, envelope and downstream trades have slipped ~2–4 weeks.
const DEMO_UPDATE_ACTS = DEMO_ACTS.map((a) => {
  const shift = (s, days) => { const d = parseDate(s); if (!d) return s; return isoOf(addDays(d, days)); };
  const m = { ...a, id: uid("a") };
  switch (a.code) {
    case "A112b": return { ...m, start: shift(a.start, 6), finish: shift(a.finish, 12), pct: 55 }; // pile caps slipped
    case "A121":  return { ...m, start: shift(a.start, 12), finish: shift(a.finish, 18), pct: 40 }; // steel frame slipped
    case "A122":  return { ...m, start: shift(a.start, 18), finish: shift(a.finish, 21), pct: 0 };  // envelope slipped
    case "A130":  return { ...m, start: shift(a.start, 14), finish: shift(a.finish, 14), pct: 0 };  // MEP shifted
    case "A140":  return { ...m, start: shift(a.start, 14), finish: shift(a.finish, 10), pct: 0 };
    case "A150":  return { ...m, start: shift(a.start, 10), finish: shift(a.finish, 10), pct: 0 };
    case "A160":  return { ...m, start: shift(a.start, 10), finish: shift(a.finish, 16), pct: 0 };  // handover pushed
    case "A170":  return { ...m, start: shift(a.start, 16), finish: shift(a.finish, 16), pct: 0 };  // substantial completion follows
    default: return m; // substructure & mobilisation held to baseline
  }
});

