// ──────────────────────────────────────────────────────────────
// DROP ZONE
// ──────────────────────────────────────────────────────────────
function DropZone({ file, onFile }) {
  const [drag, setDrag] = useState(false);
  const inputRef = useRef(null);
  const accept = (f) => f && /\.(pdf|png|jpe?g|webp|gif)$/i.test(f.name);

  const handle = (files) => {
    const f = files && files[0];
    if (!f) return;
    if (!accept(f)) { alert("Please upload a PDF or image (PNG, JPG, WEBP)."); return; }
    onFile(f);
  };

  const isImg = file && /^image\//.test(file.type);
  return (
    <div
      className={`dz ${drag ? "dz-on" : ""} ${file ? "dz-has" : ""}`}
      onDragOver={(e) => { e.preventDefault(); setDrag(true); }}
      onDragLeave={(e) => { e.preventDefault(); setDrag(false); }}
      onDrop={(e) => { e.preventDefault(); setDrag(false); handle(e.dataTransfer.files); }}
      onClick={() => inputRef.current?.click()}
      role="button" tabIndex={0}
      onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") inputRef.current?.click(); }}
    >
      <input ref={inputRef} type="file" accept=".pdf,image/*" style={{ display: "none" }}
        onChange={(e) => { handle(e.target.files); e.target.value = ""; }} />
      {file ? (
        <div className="dz-file">
          <div className="dz-file-icon">{isImg ? <ImageIcon size={22} /> : <FileText size={22} />}</div>
          <div className="dz-file-meta">
            <div className="dz-file-name">{file.name}</div>
            <div className="dz-file-sub">{isImg ? "Image" : "PDF"} · ready to extract · click to replace</div>
          </div>
          <button className="icon-btn" onClick={(e) => { e.stopPropagation(); onFile(null); }} title="Remove"><X size={16} /></button>
        </div>
      ) : (
        <>
          <Upload size={26} strokeWidth={1.4} className="dz-icon" />
          <div className="dz-headline">{drag ? "Drop to attach" : <>Drag the contractor's schedule here, <em>or click to browse</em></>}</div>
          <div className="dz-formats">PDF · PNG · JPG</div>
        </>
      )}
    </div>
  );
}

