function NewProjectModal({ onCreate, onCancel }) {
  const [form, setForm] = useState({ name: "", reference: "", address: "", client: "", generalContractor: "" });
  const [file, setFile] = useState(null);
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("");
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  const submit = async () => {
    if (!form.name.trim()) { alert("Project Name is required."); return; }
    setBusy(true);
    try {
      if (file) setStatus("Reading schedule with AI — extracting activities…");
      await onCreate(form, file, setStatus);
      // success → parent unmounts this modal
    } catch (e) {
      setBusy(false);
      setStatus("");
      alert(`Could not finish: ${e.message}\n\nThe project was still created — you can add activities manually in the Activities tab.`);
    }
  };

  return (
    <div className="backdrop" onClick={busy ? undefined : onCancel}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <h2 className="modal-title">New Project</h2>
          {!busy && <button className="icon-btn" onClick={onCancel}><X size={18} /></button>}
        </div>
        <div className="modal-body">
          <div className="fs-title">Project Information</div>
          <div className="grid2">
            <Field label="Project Name" req full icon={Building2}>
              <input className="input" autoFocus value={form.name} onChange={(e) => set("name", e.target.value)} disabled={busy} placeholder="e.g. Harbour View Mixed-Use — Block C" />
            </Field>
            <Field label="Project Reference" icon={Hash}>
              <input className="input" value={form.reference} onChange={(e) => set("reference", e.target.value)} disabled={busy} placeholder="e.g. HV-BLKC-2026" />
            </Field>
            <Field label="Project Address" icon={MapPin}>
              <input className="input" value={form.address} onChange={(e) => set("address", e.target.value)} disabled={busy} placeholder="Street, City, Region" />
            </Field>
            <Field label="Client / Owner" icon={User}>
              <input className="input" value={form.client} onChange={(e) => set("client", e.target.value)} disabled={busy} placeholder="e.g. Harbourline Holdings Ltd." />
            </Field>
            <Field label="General Contractor" icon={HardHat}>
              <input className="input" value={form.generalContractor} onChange={(e) => set("generalContractor", e.target.value)} disabled={busy} placeholder="e.g. Coastline Construction Inc." />
            </Field>
          </div>

          <div className="fs-title" style={{ marginTop: 22 }}>Baseline Schedule <span className="fs-note">— uploaded now becomes the baseline programme</span></div>
          <DropZone file={file} onFile={setFile} />
          {busy && (
            <div className="extract-status">
              <Loader2 size={15} className="spin" />
              <span>{status || "Working…"}</span>
            </div>
          )}
          {!busy && (
            <div className="hint">
              <AlertCircle size={13} />
              <span>The AI reads the PDF and proposes an activity list — you'll review and correct it before it becomes the live Gantt. You can also create the project now and add activities by hand.</span>
            </div>
          )}
        </div>
        <div className="modal-foot">
          {!busy && <button className="btn btn-ghost" onClick={onCancel}>Cancel</button>}
          <button className="btn btn-primary" onClick={submit} disabled={busy}>
            {busy ? <><Loader2 size={14} className="spin" /> Working…</> : <><Plus size={14} /> Create project</>}
          </button>
        </div>
      </div>
    </div>
  );
}

