// UPLOAD UPDATE MODAL — append a revision (programme update) to a project
// ──────────────────────────────────────────────────────────────
function UploadUpdateModal({ project, onAdd, onCancel }) {
  const [file, setFile] = useState(null);
  const [dataDate, setDataDate] = useState(todayISO());
  const [busy, setBusy] = useState(false);
  const [status, setStatus] = useState("");
  const nextLabel = `Rev ${String(project.revisions.filter((r) => !r.isBaseline).length + 1).padStart(2, "0")}`;

  const submit = async () => {
    if (!file) { alert("Attach the updated schedule PDF/image."); return; }
    setBusy(true);
    setStatus("Reading updated schedule with AI…");
    try {
      await onAdd(project, file, dataDate, nextLabel, setStatus);
    } catch (e) {
      setBusy(false); setStatus("");
      alert(`Could not finish: ${e.message}`);
    }
  };

  return (
    <div className="backdrop" onClick={busy ? undefined : onCancel}>
      <div className="modal" style={{ maxWidth: 560 }} onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <div>
            <h2 className="modal-title">Upload Programme Update</h2>
            <div className="modal-sub">Adds <b>{nextLabel}</b> to {project.name}</div>
          </div>
          {!busy && <button className="icon-btn" onClick={onCancel}><X size={18} /></button>}
        </div>
        <div className="modal-body">
          <Field label="Data Date (status date of this update)" icon={CalendarClock}>
            <input className="input" type="date" value={dataDate} onChange={(e) => setDataDate(e.target.value)} disabled={busy} />
          </Field>
          <div style={{ height: 14 }} />
          <DropZone file={file} onFile={setFile} />
          {busy && <div className="extract-status"><Loader2 size={15} className="spin" /><span>{status}</span></div>}
        </div>
        <div className="modal-foot">
          {!busy && <button className="btn btn-ghost" onClick={onCancel}>Cancel</button>}
          <button className="btn btn-primary" onClick={submit} disabled={busy}>
            {busy ? <><Loader2 size={14} className="spin" /> Working…</> : <><Layers size={14} /> Add update</>}
          </button>
        </div>
      </div>
    </div>
  );
}

