const getScopeColor = (scope) => {
  if (SCOPE_COLORS[scope]) return SCOPE_COLORS[scope];
  // Hash scope string to pick a stable palette entry
  let h = 0;
  for (let i = 0; i < (scope || "").length; i++) h = ((h << 5) - h + scope.charCodeAt(i)) | 0;
  return SCOPE_FALLBACK_PALETTE[Math.abs(h) % SCOPE_FALLBACK_PALETTE.length];
};
