// ── Helpers ────────────────────────────────────────────────────
const fmtCurrency = (n) => { const v = parseFloat(n) || 0; if (v === 0) return "—"; if (v >= 1_000_000) return `$${(v / 1_000_000).toFixed(2)}M`; if (v >= 1_000) return `$${(v / 1_000).toFixed(0)}K`; return `$${v.toFixed(0)}`; };
const fmtCurrencyFull = (n) => { const v = parseFloat(n) || 0; return v.toLocaleString("en-CA", { style: "currency", currency: "CAD", maximumFractionDigits: 0 }); };
const fmtNumber = (n) => { const v = parseFloat(n) || 0; if (v === 0) return "—"; return v.toLocaleString("en-CA", { maximumFractionDigits: 0 }); };
const uid = (prefix = "p") => prefix + "_" + Math.random().toString(36).slice(2, 9);

// ── Excel import helpers ───────────────────────────────────────
// Normalize header cells so "Job #", "JOB NO.", "job_number" all match.
const normHeader = (s) => (s || "").toString().toLowerCase().replace(/[^a-z0-9]/g, "");

// Maps a wide range of header variants → canonical project fields.
// Each canonical field lists its accepted normalized header forms.
const HEADER_ALIASES = {
  jobNumber:         ["jobnumber", "jobno", "jobnum", "job", "jobref", "projectno", "projectnumber"],
  projectName:       ["projectname", "project", "name", "jobname"],
  address:           ["address", "siteaddress", "projectaddress", "location"],
  year:              ["year", "projectyear"],
  startDate:         ["startdate", "start", "datestarted", "openeddate", "opendate", "dateopened", "date"],
  targetEndDate:     ["targetenddate", "targetend", "targetcompletion", "targetcompletiondate", "duedate", "deadline", "enddate"],
  actualEndDate:     ["actualenddate", "actualend", "completiondate", "completed", "dateclosed", "closeddate"],
  municipality:      ["municipality", "city", "town"],
  region:            ["region", "regionaldistrict", "district"],
  qs:                ["qs", "qsassigned", "qsprimary", "primaryqs", "leadqs", "quantitysurveyor"],
  status:            ["status", "projectstatus", "state"],
  client:            ["client", "lender", "clientname"],
  contact:           ["contact", "contactname", "primarycontact", "clientcontact"],
  developer:         ["developer", "developername", "owner", "sponsor"],
  projectScope:      ["projectscope", "scope", "scopeofwork", "service", "servicetype"],
  projectType:      ["projecttype", "type", "buildingtype", "assettype"],
  sfParking:         ["sfparking", "parkingsf", "parking"],
  institutional:     ["institutional", "sfinstitutional", "institutionalsf"],
  sfCommercial:      ["sfcommercial", "commercialsf", "commercial"],
  sfResidential:     ["sfresidential", "residentialsf", "residential"],
  sfGross:           ["sfgross", "grosssf", "gsf", "grosssqft", "grossarea"],
  storys:            ["storys", "stories", "storey", "storeys", "numfloors", "floors"],
  units:             ["units", "numunits", "unitcount"],
  lots:              ["lots", "numlots", "lotcount"],
  landCost:          ["landcost", "land"],
  softCost:          ["softcost", "soft", "softcosts"],
  financeCost:       ["financecost", "finance", "financingcost", "financingcosts"],
  hardCost:          ["hardcost", "hard", "hardcosts", "construction", "constructioncost"],
  contingency:       ["contingency", "contingencycost"],
  gstCosts:          ["gstcosts", "gst", "salestax", "tax"],
  cmhcCosts:         ["cmhccosts", "cmhc", "cmhcfees"],
  totalProjectCosts: ["totalprojectcosts", "totalcost", "totalcosts", "total", "projectcost"],
  flag:              ["flag", "flagcode"],
};

// Build a reverse lookup: normalized header → canonical field
const buildHeaderMap = (headerRow) => {
  const map = {};
  headerRow.forEach((rawHeader, colIdx) => {
    const norm = normHeader(rawHeader);
    if (!norm) return;
    for (const [field, aliases] of Object.entries(HEADER_ALIASES)) {
      if (aliases.includes(norm)) {
        // First match wins — don't let later columns override
        if (map[field] === undefined) map[field] = colIdx;
        break;
      }
    }
  });
  return map;
};

// Convert an Excel cell value into a YYYY-MM-DD string.
// Handles JS Date objects (cellDates: true), serial numbers, and strings.
const cellToDate = (v) => {
  if (!v && v !== 0) return "";
  if (v instanceof Date) {
    if (isNaN(v)) return "";
    const yr = v.getFullYear(), mo = String(v.getMonth() + 1).padStart(2, "0"), dy = String(v.getDate()).padStart(2, "0");
    return `${yr}-${mo}-${dy}`;
  }
  if (typeof v === "number") {
    // Excel serial date: 1 = 1900-01-01 (with the well-known leap bug). SheetJS handles this if cellDates is true.
    // Fallback: convert serial manually.
    const epoch = new Date(Date.UTC(1899, 11, 30));
    const d = new Date(epoch.getTime() + v * 86400000);
    if (isNaN(d)) return "";
    return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, "0")}-${String(d.getUTCDate()).padStart(2, "0")}`;
  }
  const s = v.toString().trim();
  if (!s) return "";
  // Already ISO?
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  // Try Date parse as last resort
  const d = new Date(s);
  if (!isNaN(d)) {
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  }
  return s;
};

const cellToNumber = (v) => {
  if (v === null || v === undefined || v === "") return 0;
  if (typeof v === "number") return v;
  const cleaned = v.toString().replace(/[$,\s]/g, "");
  const n = parseFloat(cleaned);
  return isNaN(n) ? 0 : n;
};

const cellToString = (v) => (v === null || v === undefined) ? "" : v.toString().trim();

// Map status values from various conventions to our canonical set
const normalizeImportedStatus = (raw) => {
  const s = (raw || "").toString().trim().toUpperCase();
  if (!s) return "ACTIVE";
  if (s === "IN PROGRESS" || s === "ACTIVE" || s === "WIP" || s === "IN-PROGRESS") return "ACTIVE";
  if (s === "COMPLETE" || s === "COMPLETED" || s === "DONE" || s === "FINISHED") return "COMPLETED";
  if (s === "ON HOLD" || s === "HOLD" || s === "ON-HOLD" || s === "PAUSED") return "ON HOLD";
  if (s === "DEAD" || s === "CANCELLED" || s === "CANCELED" || s === "KILLED") return "CANCELLED";
  return STATUS_OPTIONS.includes(s) ? s : "ACTIVE";
};

const normalizeImportedQs = (raw) => {
  const s = (raw || "").toString().trim();
  if (!s) return "";
  if (QS_ROSTER.includes(s)) return s;
  const byInitials = QS_ROSTER.find((n) => qsInitials(n) === s.toUpperCase());
  if (byInitials) return byInitials;
  const byLast = QS_ROSTER.find((n) => n.toLowerCase().includes(s.toLowerCase()) || s.toLowerCase().includes(n.toLowerCase()));
  return byLast || "";
};

// Turn one raw Excel row + headerMap into a project record. Returns null if no job # or no name.
const rowToProject = (row, headerMap) => {
  const get = (field) => {
    const idx = headerMap[field];
    return idx === undefined ? undefined : row[idx];
  };
  const jobNumber = cellToNumber(get("jobNumber"));
  const projectName = cellToString(get("projectName"));
  if (!jobNumber && !projectName) return null;

  // Compute total if not provided
  const provided = {
    landCost: cellToNumber(get("landCost")),
    softCost: cellToNumber(get("softCost")),
    financeCost: cellToNumber(get("financeCost")),
    hardCost: cellToNumber(get("hardCost")),
    contingency: cellToNumber(get("contingency")),
    gstCosts: cellToNumber(get("gstCosts")),
    cmhcCosts: cellToNumber(get("cmhcCosts")),
  };
  const explicitTotal = cellToNumber(get("totalProjectCosts"));
  const computedTotal = Object.values(provided).reduce((s, n) => s + n, 0);
  const totalProjectCosts = explicitTotal > 0 ? explicitTotal : computedTotal;

  const sfGross = cellToNumber(get("sfGross"));
  const costPerSf = sfGross > 0 ? provided.hardCost / sfGross : 0;

  return {
    id: uid(),
    flag: cellToString(get("flag")) || "P",
    jobNumber: jobNumber || "",
    projectName: projectName || `(Untitled — Job ${jobNumber || "?"})`,
    address: cellToString(get("address")),
    year: cellToNumber(get("year")) || (get("startDate") ? new Date(cellToDate(get("startDate"))).getFullYear() : new Date().getFullYear()),
    startDate: cellToDate(get("startDate")),
    targetEndDate: cellToDate(get("targetEndDate")),
    actualEndDate: cellToDate(get("actualEndDate")),
    municipality: cellToString(get("municipality")),
    region: cellToString(get("region")),
    qs: normalizeImportedQs(get("qs")),
    status: normalizeImportedStatus(get("status")),
    client: cellToString(get("client")),
    contact: cellToString(get("contact")),
    developer: cellToString(get("developer")),
    projectScope: (cellToString(get("projectScope")) || "COST PLANNING").toUpperCase(),
    projectType: (cellToString(get("projectType")) || "COMMERCIAL").toUpperCase(),
    sfParking: cellToNumber(get("sfParking")),
    institutional: cellToNumber(get("institutional")),
    sfCommercial: cellToNumber(get("sfCommercial")),
    sfResidential: cellToNumber(get("sfResidential")),
    sfGross,
    storys: cellToNumber(get("storys")),
    units: cellToNumber(get("units")),
    lots: cellToNumber(get("lots")),
    ...provided,
    totalProjectCosts,
    costPerSf,
    awaitingSubmission: false,
  };
};

// Find the row that looks like headers (must contain at least 2 recognizable fields).
// Returns { headerRow, headerRowIdx } or null.
const findHeaderRow = (rows) => {
  for (let i = 0; i < Math.min(rows.length, 10); i++) {
    const headerMap = buildHeaderMap(rows[i]);
    if (Object.keys(headerMap).length >= 2) {
      return { headerRow: rows[i], headerMap, headerRowIdx: i };
    }
  }
  return null;
};

// Top-level: parse an ArrayBuffer (uploaded xlsx/csv) → { projects, errors, fileName }
const parseProjectFile = (arrayBuffer, fileName) => {
  const errors = [];
  let projects = [];
  try {
    const wb = XLSX.read(arrayBuffer, { type: "array", cellDates: true });
    const wsName = wb.SheetNames[0];
    if (!wsName) {
      errors.push("No sheets found in workbook.");
      return { projects: [], errors, fileName };
    }
    const ws = wb.Sheets[wsName];
    const rows = XLSX.utils.sheet_to_json(ws, { header: 1, defval: "", raw: false, dateNF: "yyyy-mm-dd" });
    if (rows.length < 2) {
      errors.push("Sheet has fewer than 2 rows — need at least a header row and one data row.");
      return { projects: [], errors, fileName };
    }
    const found = findHeaderRow(rows);
    if (!found) {
      errors.push("Couldn't identify a header row. The first 10 rows didn't contain at least two recognizable column names (job number, project name, client, etc.).");
      return { projects: [], errors, fileName };
    }
    const { headerMap, headerRowIdx } = found;
    for (let i = headerRowIdx + 1; i < rows.length; i++) {
      const row = rows[i];
      if (!row || row.every((c) => c === "" || c === null || c === undefined)) continue;
      const proj = rowToProject(row, headerMap);
      if (proj) projects.push(proj);
    }
    if (projects.length === 0) errors.push("No usable rows found below the header.");
  } catch (e) {
    errors.push(`Couldn't parse the file: ${e.message}`);
  }
  return { projects, errors, fileName };
};

// ── Small components ───────────────────────────────────────────
function KpiCard({ icon: Icon, label, value, sublabel, accent, filter }) {
  return (
    <div className="kpi-card">
      {/* Optional filter slot — top-left, next to the icon when present. Used for
          KPIs that show a per-category breakdown (Active SF, Total Units). */}
      {filter && <div className="kpi-filter">{filter}</div>}
      <div className="kpi-icon" style={{ background: accent }}><Icon size={18} strokeWidth={1.75} /></div>
      <div className="kpi-label">{label}</div>
      <div className="kpi-value">{value}</div>
      {sublabel && <div className="kpi-sublabel">{sublabel}</div>}
    </div>
  );
}

function StatusPill({ status }) {
  const color = STATUS_COLORS[status] || "var(--sky)";
  return (
    <span className="status-pill" style={{ color, borderColor: color }}>
      <span className="status-dot" style={{ background: color }} />
      {status || "—"}
    </span>
  );
}

// Scope-coded pastel tag. Color comes from getScopeColor() so known scopes get
// their assigned hue and unknown scopes get a stable fallback from the palette.
function ScopeTag({ scope }) {
  const c = getScopeColor(scope);
  return (
    <span
      className="scope-tag"
      style={{ background: c.bg, borderColor: c.border, color: c.text }}
    >{scope || "—"}</span>
  );
}

function Field({ label, required, full, children }) {
  return (
    <div className={`field ${full ? "field-full" : ""}`}>
      <label className="field-label">{label}{required && <span className="field-req">*</span>}</label>
      {children}
    </div>
  );
}

function ConfirmDelete({ title, body, onCancel, onConfirm }) {
  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <div className="modal" style={{ maxWidth: 440 }} onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2 className="modal-title">{title}</h2>
          <button className="icon-btn" onClick={onCancel}><X size={18} /></button>
        </div>
        <div className="modal-body" style={{ paddingTop: 8 }}>
          <p style={{ margin: 0, fontSize: 13, color: "var(--ink)", lineHeight: 1.55 }}>{body}</p>
        </div>
        <div className="modal-footer">
          <button className="btn btn-ghost" onClick={onCancel}>Cancel</button>
          <button className="btn btn-danger" onClick={onConfirm}><Trash2 size={13} /> Delete</button>
        </div>
      </div>
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// ENTITY VIEW (used by both Lenders and Developers)
// ──────────────────────────────────────────────────────────────
function EntityView({ kind, entities, projects, onAdd, onEdit, onDelete, onAddContact, onEditContact, onDeleteContact, onViewContact, onViewProject }) {
  const cfg = ENTITY_CONFIGS[kind];
  const Icon = cfg.icon;

  const [search, setSearch] = useState("");
  const [typeFilter, setTypeFilter] = useState("all");
  const [expandedIds, setExpandedIds] = useState(() => new Set(entities.map((e) => e.id)));

  const entityStats = useMemo(() => {
    const stats = {};
    entities.forEach((e) => {
      const matched = projects.filter((p) => {
        // An explicit link wins outright, so a project can never show
        // under two organisations because a name happens to coincide.
        if (cfg.idField && p[cfg.idField]) return p[cfg.idField] === e.id;
        const names = cfg.nameFields || [cfg.matchField];
        return names.some((f) => (p[f] || "").toLowerCase() === e.name.toLowerCase());
      });
      const active = matched.filter((p) => p.status === "ACTIVE");
      stats[e.id] = {
        totalProjects: matched.length,
        activeProjects: active.length,
        totalExposure: active.reduce((s, p) => s + (parseFloat(p.totalProjectCosts) || 0), 0),
        projects: matched,
      };
    });
    return stats;
  }, [entities, projects, cfg.matchField]);

  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return entities.filter((e) => {
      const nameMatch = q === "" || e.name.toLowerCase().includes(q) ||
        (e.staff || []).some((s) => s.name.toLowerCase().includes(q) || (s.title || "").toLowerCase().includes(q));
      const typeMatch = typeFilter === "all" || e.type === typeFilter;
      return nameMatch && typeMatch;
    });
  }, [entities, search, typeFilter]);

  const toggle = (id) => {
    setExpandedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };
  const expandAll = () => setExpandedIds(new Set(filtered.map((e) => e.id)));
  const collapseAll = () => setExpandedIds(new Set());

  const totalContacts = entities.reduce((s, e) => s + (e.staff?.length || 0), 0);
  const totalExposure = Object.values(entityStats).reduce((s, x) => s + x.totalExposure, 0);
  const totalActive = Object.values(entityStats).reduce((s, x) => s + x.activeProjects, 0);

  return (
    <div className="lenders-wrap">
      <div className="kpi-grid">
        <KpiCard icon={Icon} label={cfg.labelPlural} value={entities.length} sublabel={cfg.kpiSubLeft} accent="var(--navy)" />
        <KpiCard icon={User} label="Contacts" value={totalContacts} sublabel={`across all ${cfg.labelPlural.toLowerCase()}`} accent="var(--steel)" />
        <KpiCard icon={Briefcase} label="Active Engagements" value={totalActive} sublabel="ongoing projects" accent="var(--indigo)" />
        <KpiCard icon={DollarSign} label={cfg.kpiExposureLabel} value={fmtCurrency(totalExposure)} sublabel={cfg.kpiSubExposure} accent="#5a8c6f" />
      </div>

      <div className="lenders-toolbar">
        <div className="filter-search">
          <Search size={15} />
          <input placeholder={`Search ${cfg.label.toLowerCase()} or contact...`} value={search} onChange={(e) => setSearch(e.target.value)} />
          {search && <button className="icon-btn icon-btn-small" onClick={() => setSearch("")}><X size={13} /></button>}
        </div>
        <select className="filter-select" value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)}>
          <option value="all">All types</option>
          {cfg.typeOptions.map((t) => <option key={t}>{t}</option>)}
        </select>
        <div className="toolbar-spacer" />
        <button className="btn btn-ghost" onClick={expandAll}>Expand all</button>
        <button className="btn btn-ghost" onClick={collapseAll}>Collapse all</button>
        <button className="btn btn-primary" onClick={onAdd}><Plus size={14} /> New {cfg.label}</button>
      </div>

      {filtered.length === 0 ? (
        <div className="lender-empty">
          <Icon size={28} strokeWidth={1.25} />
          <div className="lender-empty-title">No {cfg.labelPlural.toLowerCase()} match</div>
          <div className="lender-empty-sub">Try a different search or add a new {cfg.label.toLowerCase()}.</div>
        </div>
      ) : (
        <div className="lender-list">
          {filtered.map((entity) => {
            const stats = entityStats[entity.id] || { totalProjects: 0, activeProjects: 0, totalExposure: 0, projects: [] };
            const expanded = expandedIds.has(entity.id);
            return (
              <div key={entity.id} className={`lender-card ${expanded ? "lender-card-open" : ""}`}>
                <div className="lender-header" onClick={() => toggle(entity.id)}>
                  <button className="lender-chevron" aria-label={expanded ? "Collapse" : "Expand"}>
                    {expanded ? <ChevronDown size={16} /> : <ChevronRight size={16} />}
                  </button>
                  <div className="lender-id">
                    <div className="lender-name-row">
                      <Icon size={16} className="lender-icon" />
                      <h3 className="lender-name">{entity.name}</h3>
                      <span className="lender-type-tag">{entity.type}</span>
                    </div>
                    {entity.notes && <div className="lender-notes">{entity.notes}</div>}
                  </div>
                  <div className="lender-stats">
                    <div className="lender-stat"><span className="lender-stat-num">{entity.staff?.length || 0}</span><span className="lender-stat-lbl">contacts</span></div>
                    <div className="lender-stat"><span className="lender-stat-num">{stats.activeProjects}</span><span className="lender-stat-lbl">active</span></div>
                    <div className="lender-stat"><span className="lender-stat-num">{fmtCurrency(stats.totalExposure)}</span><span className="lender-stat-lbl">{cfg.statExposureLabel}</span></div>
                  </div>
                  <div className="lender-actions" onClick={(e) => e.stopPropagation()}>
                    <button className="icon-btn" onClick={() => onEdit(entity)} title={`Edit ${cfg.label.toLowerCase()}`}><Edit2 size={14} /></button>
                    <button className="icon-btn icon-btn-danger" onClick={() => onDelete(entity)} title={`Delete ${cfg.label.toLowerCase()}`}><Trash2 size={14} /></button>
                  </div>
                </div>

                {expanded && (
                  <div className="lender-body">
                    <div className="lender-body-section">
                      <div className="lender-body-title">
                        <span>Contacts{cfg.groupProjectsByContact && stats.projects.length > 0 ? " & Projects" : ""}</span>
                        <button className="btn-inline" onClick={() => onAddContact(entity)}>
                          <UserPlus size={12} /> Add contact
                        </button>
                      </div>

                      {cfg.groupProjectsByContact ? (
                        // GROUPED: each contact carries their projects nested below
                        (() => {
                          const staff = entity.staff || [];
                          const normName = (s) => (s || "").trim().toLowerCase();
                          const statusRank = { ACTIVE: 0, "ON HOLD": 1, COMPLETED: 2, CANCELLED: 3 };
                          const sortProjects = (arr) => [...arr].sort((a, b) => {
                            const sa = statusRank[a.status] ?? 9, sb = statusRank[b.status] ?? 9;
                            if (sa !== sb) return sa - sb;
                            return (b.startDate || "").localeCompare(a.startDate || "");
                          });
                          const staffNamesLower = new Set(staff.map((s) => normName(s.name)));
                          // For a lender the relevant person is the file manager;
                          // `contact` is the client-side contact and is only a fallback.
                          const personOf = (p) => {
                            const fields = cfg.contactFields || ["contact"];
                            for (const f of fields) { if (p[f]) return p[f]; }
                            return "";
                          };
                          const orphans = sortProjects(stats.projects.filter((p) => !staffNamesLower.has(normName(personOf(p)))));

                          if (staff.length === 0 && stats.projects.length === 0) {
                            return <div className="contact-empty">No contacts recorded.</div>;
                          }

                          return (
                            <div className="contact-groups">
                              {staff.map((person) => {
                                const personProjects = sortProjects(
                                  stats.projects.filter((p) => normName(personOf(p)) === normName(person.name))
                                );
                                return (
                                  <div key={person.id} className="contact-group">
                                    <div className="contact-item">
                                      <div className="contact-rail" />
                                      <div className="contact-main">
                                        <button
                                          type="button"
                                          className="contact-name contact-name-clickable"
                                          onClick={() => onViewContact && onViewContact(entity, person)}
                                          title="Open contact detail"
                                        >{person.name}</button>
                                        {person.title && <div className="contact-title">{person.title}</div>}
                                        <div className="contact-detail-row">
                                          {person.email && <a className="contact-detail" href={`mailto:${person.email}`}><Mail size={11} /> {person.email}</a>}
                                          {(person.officePhone || person.cellPhone || person.phone) && (
                                            <a className="contact-detail" href={`tel:${person.officePhone || person.cellPhone || person.phone}`}>
                                              <Phone size={11} /> {person.officePhone || person.cellPhone || person.phone}
                                            </a>
                                          )}
                                          {!person.email && !person.officePhone && !person.cellPhone && !person.phone && (
                                            <span className="contact-detail contact-detail-empty">No contact info on file</span>
                                          )}
                                        </div>
                                      </div>
                                      <div className="contact-actions">
                                        <button className="icon-btn icon-btn-small" onClick={() => onEditContact(entity, person)} title="Edit contact"><Edit2 size={12} /></button>
                                        <button className="icon-btn icon-btn-small icon-btn-danger" onClick={() => onDeleteContact(entity, person)} title="Delete contact"><Trash2 size={12} /></button>
                                      </div>
                                    </div>
                                    {personProjects.length > 0 ? (
                                      <ul className="contact-projects">
                                        {personProjects.map((p) => (
                                          <li key={p.id} className="contact-project-row">
                                            <span className="contact-project-job mono">#{p.jobNumber}</span>
                                            <button
                                              type="button"
                                              className="contact-project-name project-name-clickable"
                                              onClick={() => onViewProject && onViewProject(p)}
                                              title="Open project notes"
                                            >{p.projectName}</button>
                                            <span className="contact-project-status"><StatusPill status={p.status} /></span>
                                            <span className="mono contact-project-val">{fmtCurrencyFull(p.totalProjectCosts)}</span>
                                          </li>
                                        ))}
                                      </ul>
                                    ) : (
                                      <div className="contact-projects-empty">No projects associated with this contact.</div>
                                    )}
                                  </div>
                                );
                              })}

                              {orphans.length > 0 && (
                                <div className="contact-group contact-group-orphan">
                                  <div className="contact-orphan-header">
                                    Projects without a matched contact <span className="contact-orphan-count">({orphans.length})</span>
                                  </div>
                                  <ul className="contact-projects contact-projects-orphan">
                                    {orphans.map((p) => (
                                      <li key={p.id} className="contact-project-row contact-project-row-orphan">
                                        <span className="contact-project-job mono">#{p.jobNumber}</span>
                                        <button
                                          type="button"
                                          className="contact-project-name project-name-clickable"
                                          onClick={() => onViewProject && onViewProject(p)}
                                          title="Open project notes"
                                        >
                                          {p.projectName}
                                          {p.contact && <span className="contact-orphan-tag">contact: {p.contact}</span>}
                                        </button>
                                        <span className="contact-project-status"><StatusPill status={p.status} /></span>
                                        <span className="mono contact-project-val">{fmtCurrencyFull(p.totalProjectCosts)}</span>
                                      </li>
                                    ))}
                                  </ul>
                                </div>
                              )}
                            </div>
                          );
                        })()
                      ) : (
                        // FLAT: developers — original layout, contacts only
                        (!entity.staff || entity.staff.length === 0) ? (
                          <div className="contact-empty">No contacts recorded.</div>
                        ) : (
                          <ul className="contact-list">
                            {entity.staff.map((person) => (
                              <li key={person.id} className="contact-item">
                                <div className="contact-rail" />
                                <div className="contact-main">
                                  <button
                                    type="button"
                                    className="contact-name contact-name-clickable"
                                    onClick={() => onViewContact && onViewContact(entity, person)}
                                    title="Open contact detail"
                                  >{person.name}</button>
                                  {person.title && <div className="contact-title">{person.title}</div>}
                                  <div className="contact-detail-row">
                                    {person.email && <a className="contact-detail" href={`mailto:${person.email}`}><Mail size={11} /> {person.email}</a>}
                                    {(person.officePhone || person.cellPhone || person.phone) && (
                                      <a className="contact-detail" href={`tel:${person.officePhone || person.cellPhone || person.phone}`}>
                                        <Phone size={11} /> {person.officePhone || person.cellPhone || person.phone}
                                      </a>
                                    )}
                                    {!person.email && !person.officePhone && !person.cellPhone && !person.phone && (
                                      <span className="contact-detail contact-detail-empty">No contact info on file</span>
                                    )}
                                  </div>
                                </div>
                                <div className="contact-actions">
                                  <button className="icon-btn icon-btn-small" onClick={() => onEditContact(entity, person)} title="Edit contact"><Edit2 size={12} /></button>
                                  <button className="icon-btn icon-btn-small icon-btn-danger" onClick={() => onDeleteContact(entity, person)} title="Delete contact"><Trash2 size={12} /></button>
                                </div>
                              </li>
                            ))}
                          </ul>
                        )
                      )}
                    </div>

                    {/* Flat Projects section only for non-grouped entities (Developers) */}
                    {!cfg.groupProjectsByContact && stats.projects.length > 0 && (
                      <div className="lender-body-section">
                        <div className="lender-body-title"><span>Projects ({stats.totalProjects})</span></div>
                        <ul className="lender-projects">
                          {stats.projects.slice(0, 6).map((p) => (
                            <li key={p.id} className="lender-project-row">
                              <span className="lender-project-job mono">#{p.jobNumber}</span>
                              <button
                                type="button"
                                className="lender-project-name project-name-clickable"
                                onClick={() => onViewProject && onViewProject(p)}
                                title="Open project notes"
                              >{p.projectName}</button>
                              <span className="lender-project-status"><StatusPill status={p.status} /></span>
                              <span className="mono lender-project-val">{fmtCurrencyFull(p.totalProjectCosts)}</span>
                            </li>
                          ))}
                          {stats.projects.length > 6 && <li className="lender-project-more">+ {stats.projects.length - 6} more</li>}
                        </ul>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ── Entity Form (shared for lender + developer) ─────────────────
function EntityForm({ kind, entity, onSave, onCancel }) {
  const cfg = ENTITY_CONFIGS[kind];
  const [form, setForm] = useState(entity || { id: uid(cfg.idPrefix), name: "", type: cfg.defaultType, notes: "", staff: [] });
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  const submit = () => { if (!form.name.trim()) { alert(`${cfg.label} name is required`); return; } onSave(form); };

  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <div className="modal" style={{ maxWidth: 520 }} onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2 className="modal-title">{entity ? `Edit ${cfg.label}` : `New ${cfg.label}`}</h2>
          <button className="icon-btn" onClick={onCancel}><X size={18} /></button>
        </div>
        <div className="modal-body">
          <div className="form-grid form-grid-2">
            <Field label={`${cfg.label} Name`} required full>
              <input className="input" value={form.name} onChange={(e) => set("name", e.target.value)} autoFocus />
            </Field>
            <Field label="Type" full>
              <select className="input" value={form.type} onChange={(e) => set("type", e.target.value)}>
                {cfg.typeOptions.map((t) => <option key={t}>{t}</option>)}
              </select>
            </Field>
            <Field label="Notes" full>
              <textarea className="input" rows={3} value={form.notes} onChange={(e) => set("notes", e.target.value)} placeholder={cfg.formNotesPlaceholder} />
            </Field>
          </div>
        </div>
        <div className="modal-footer">
          <button className="btn btn-ghost" onClick={onCancel}>Cancel</button>
          <button className="btn btn-primary" onClick={submit}><Save size={14} /> {entity ? "Save changes" : `Add ${cfg.label.toLowerCase()}`}</button>
        </div>
      </div>
    </div>
  );
}

// ── Contact Form ────────────────────────────────────────────────
// ──────────────────────────────────────────────────────────────
// CONTACT DETAIL MODAL — opens when clicking a contact's name on a lender or
// developer card. Read-friendly view of all contact info plus an editable
// comments thread (add, edit, delete individual comments).
// ──────────────────────────────────────────────────────────────
// ──────────────────────────────────────────────────────────────
// NOTES THREAD — reusable bulleted comments list with add/edit/delete.
// Used by both the contact-detail modal (per-contact comments) and the
// project notes section (per-project notes). When `readOnly` is true the
// editing controls and add input are hidden — used on the Lenders/Developers
// tab modals where notes are view-only.
// ──────────────────────────────────────────────────────────────
function NotesThread({
  items,                 // array of { id, text, ts, edited? }
  onAdd,                 // (text) => void
  onEdit,                // (id, text) => void
  onDelete,              // (id) => void
  readOnly = false,
  placeholder = "Add a note…",
  emptyMessage = "No notes yet.",
  addButtonLabel = "Add note",
  confirmDeleteLabel = "Delete this note?",
}) {
  const [draft, setDraft] = useState("");
  const [editingId, setEditingId] = useState(null);
  const [editDraft, setEditDraft] = useState("");

  const startEdit = (n) => { setEditingId(n.id); setEditDraft(n.text); };
  const cancelEdit = () => { setEditingId(null); setEditDraft(""); };
  const saveEdit = () => {
    const text = editDraft.trim();
    if (!text) { cancelEdit(); return; }
    onEdit && onEdit(editingId, text);
    cancelEdit();
  };
  const addOne = () => {
    const text = draft.trim();
    if (!text) return;
    onAdd && onAdd(text);
    setDraft("");
  };
  const deleteOne = (id) => {
    if (!window.confirm(confirmDeleteLabel)) return;
    onDelete && onDelete(id);
  };
  const fmtTs = (ts) => {
    if (!ts) return "";
    // Date and time: a note is far more useful with the hour attached, and two
    // notes on the same day are otherwise indistinguishable.
    const d = new Date(ts);
    return d.toLocaleDateString("en-CA", { year: "numeric", month: "short", day: "numeric" })
      + " at " + d.toLocaleTimeString("en-CA", { hour: "2-digit", minute: "2-digit", hour12: false });
  };

  return (
    <div className="notes-thread">
      {items.length === 0 ? (
        <div className="cd-comments-empty">{emptyMessage}</div>
      ) : (
        <ul className="cd-comments-list">
          {items.map((n) => (
            <li key={n.id} className="cd-comment">
              {editingId === n.id ? (
                <div className="cd-comment-edit">
                  <textarea
                    className="input"
                    rows={2}
                    value={editDraft}
                    onChange={(e) => setEditDraft(e.target.value)}
                    autoFocus
                  />
                  <div className="cd-comment-edit-actions">
                    <button className="btn btn-ghost" onClick={cancelEdit}>Cancel</button>
                    <button className="btn btn-primary" onClick={saveEdit}><Save size={12} /> Save</button>
                  </div>
                </div>
              ) : (
                <>
                  <div className="cd-comment-bullet">•</div>
                  <div className="cd-comment-body">
                    <div className="cd-comment-text">{n.text}</div>
                    <div className="cd-comment-meta">
                      {fmtTs(n.ts)}
                      {n.edited && <span className="cd-comment-edited"> · edited {fmtTs(n.edited)}</span>}
                    </div>
                  </div>
                  {!readOnly && (
                    <div className="cd-comment-actions">
                      <button className="icon-btn icon-btn-small" onClick={() => startEdit(n)} title="Edit"><Edit2 size={12} /></button>
                      <button className="icon-btn icon-btn-small icon-btn-danger" onClick={() => deleteOne(n.id)} title="Delete"><Trash2 size={12} /></button>
                    </div>
                  )}
                </>
              )}
            </li>
          ))}
        </ul>
      )}

      {!readOnly && (
        <div className="cd-add">
          <textarea
            className="input"
            rows={2}
            placeholder={placeholder}
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if ((e.ctrlKey || e.metaKey) && e.key === "Enter") addOne();
            }}
          />
          <button
            className="btn btn-primary"
            onClick={addOne}
            disabled={!draft.trim()}
          ><Plus size={13} /> {addButtonLabel}</button>
        </div>
      )}
    </div>
  );
}

function ContactDetail({ entity, contact, onSave, onClose }) {
  // Local working copy so edits batch until the user dismisses the modal.
  // onSave receives the full updated contact whenever a change is committed.
  const [local, setLocal] = useState(contact);

  // Sync local copy if the parent updates the contact (e.g. after EntityForm save)
  useEffect(() => { setLocal(contact); }, [contact?.id]);

  const commit = (next) => { setLocal(next); onSave(next); };

  const officePhone = local.officePhone || local.phone || "";
  const cellPhone = local.cellPhone || "";
  const fax = local.fax || "";
  const comments = local.comments || [];

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal cd-modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <div>
            <h2 className="modal-title">{local.name}</h2>
            <div className="modal-subtitle">
              {local.title && <>{local.title} · </>}<b>{entity.name}</b>
            </div>
          </div>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>

        <div className="modal-body">
          {/* Contact info block */}
          <div className="cd-info">
            {officePhone ? (
              <a className="cd-info-row" href={`tel:${officePhone}`}>
                <span className="cd-info-label">Office</span>
                <span className="cd-info-value">{officePhone}</span>
              </a>
            ) : (
              <div className="cd-info-row cd-info-row-empty">
                <span className="cd-info-label">Office</span>
                <span className="cd-info-value">—</span>
              </div>
            )}
            {cellPhone ? (
              <a className="cd-info-row" href={`tel:${cellPhone}`}>
                <span className="cd-info-label">Cell</span>
                <span className="cd-info-value">{cellPhone}</span>
              </a>
            ) : (
              <div className="cd-info-row cd-info-row-empty">
                <span className="cd-info-label">Cell</span>
                <span className="cd-info-value">—</span>
              </div>
            )}
            {fax ? (
              <div className="cd-info-row cd-info-row-static">
                <span className="cd-info-label">Fax</span>
                <span className="cd-info-value">{fax}</span>
              </div>
            ) : (
              <div className="cd-info-row cd-info-row-empty">
                <span className="cd-info-label">Fax</span>
                <span className="cd-info-value">—</span>
              </div>
            )}
            {local.email ? (
              <a className="cd-info-row" href={`mailto:${local.email}`}>
                <span className="cd-info-label">Email</span>
                <span className="cd-info-value">{local.email}</span>
              </a>
            ) : (
              <div className="cd-info-row cd-info-row-empty">
                <span className="cd-info-label">Email</span>
                <span className="cd-info-value">—</span>
              </div>
            )}
          </div>

          {/* Comments thread */}
          <div className="cd-comments">
            <div className="cd-comments-title">Comments</div>
            <NotesThread
              items={comments}
              onAdd={(text) => {
                const entry = { id: uid("cm"), text, ts: Date.now() };
                commit({ ...local, comments: [...comments, entry] });
              }}
              onEdit={(id, text) => commit({
                ...local,
                comments: comments.map((c) => c.id === id ? { ...c, text, edited: Date.now() } : c),
              })}
              onDelete={(id) => commit({ ...local, comments: comments.filter((c) => c.id !== id) })}
              placeholder="Add a comment — meeting notes, deal terms, follow-up reminders…"
              emptyMessage="No comments yet. Add one below to start a record."
              addButtonLabel="Add comment"
              confirmDeleteLabel="Delete this comment?"
            />
          </div>
        </div>

        <div className="modal-footer">
          <button className="btn btn-ghost" onClick={onClose}>Close</button>
        </div>
      </div>
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// PROJECT NOTES MODAL — read-only viewer for project notes. Opened from the
// Lenders + Developers tabs when a user clicks a project name. Editing must
// happen on the Projects tab itself; this modal is intentionally view-only
// so notes have one source of truth and one editing surface.
