function ContactForm({ entity, contact, onSave, onCancel }) {
  const [form, setForm] = useState(contact || {
    id: uid("c"), name: "", title: "",
    officePhone: "", cellPhone: "", fax: "",
    email: "", phone: "", // legacy field retained for back-compat
    notes: "", comments: [],
  });
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  const submit = () => { if (!form.name.trim()) { alert("Contact name is required"); return; } onSave(form); };

  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <div className="modal" style={{ maxWidth: 560 }} onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <div>
            <h2 className="modal-title">{contact ? "Edit Contact" : "New Contact"}</h2>
            <div className="modal-subtitle">at <b>{entity.name}</b></div>
          </div>
          <button className="icon-btn" onClick={onCancel}><X size={18} /></button>
        </div>
        <div className="modal-body">
          <div className="form-grid form-grid-2">
            <Field label="Name" required full><input className="input" value={form.name} onChange={(e) => set("name", e.target.value)} autoFocus /></Field>
            <Field label="Title" full><input className="input" value={form.title} onChange={(e) => set("title", e.target.value)} placeholder="e.g. Senior Account Manager" /></Field>
            <Field label="Office Phone"><input className="input" type="tel" value={form.officePhone || ""} onChange={(e) => set("officePhone", e.target.value)} placeholder="250-555-0100" /></Field>
            <Field label="Cell"><input className="input" type="tel" value={form.cellPhone || ""} onChange={(e) => set("cellPhone", e.target.value)} placeholder="250-555-0200" /></Field>
            <Field label="Fax"><input className="input" type="tel" value={form.fax || ""} onChange={(e) => set("fax", e.target.value)} /></Field>
            <Field label="Email"><input className="input" type="email" value={form.email} onChange={(e) => set("email", e.target.value)} /></Field>
          </div>
          <div className="contact-form-note">
            <i>Comments are managed from the contact detail view — click a contact's name in the lender card to open it.</i>
          </div>
        </div>
        <div className="modal-footer">
          <button className="btn btn-ghost" onClick={onCancel}>Cancel</button>
          <button className="btn btn-primary" onClick={submit}><Save size={14} /> {contact ? "Save changes" : "Add contact"}</button>
        </div>
      </div>
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// OVERVIEW VIEW
// ──────────────────────────────────────────────────────────────
function OverviewView({ projects, onProjectUpdate, onEditProject }) {
  // Per-card filters for the SF / Units breakdowns. "all" = no filter.
  const [gsfTypeFilter, setGsfTypeFilter] = useState("all");
  const [unitsTypeFilter, setUnitsTypeFilter] = useState("all");

  const kpis = useMemo(() => {
    const active = projects.filter((p) => p.status === "ACTIVE");
    const onHold = projects.filter((p) => p.status === "ON HOLD");
    const totalActiveValue = active.reduce((s, p) => s + (parseFloat(p.totalProjectCosts) || 0), 0);

    // Active GSF — optionally filtered to a single project type
    const activeForGsf = gsfTypeFilter === "all" ? active : active.filter((p) => p.projectType === gsfTypeFilter);
    const totalActiveGsf = activeForGsf.reduce((s, p) => s + (parseFloat(p.sfGross) || 0), 0);

    // All-time totals for the second KPI row
    const totalValue = projects.reduce((s, p) => s + (parseFloat(p.totalProjectCosts) || 0), 0);

    // Total Units — optionally filtered to a single project type
    const projForUnits = unitsTypeFilter === "all" ? projects : projects.filter((p) => p.projectType === unitsTypeFilter);
    const totalUnits = projForUnits.reduce((s, p) => s + (parseFloat(p.units) || 0), 0);

    // "Cost plans provided" = all-time COST PLANNING engagements, any status.
    // If you'd rather count only COMPLETED ones, change the filter below.
    const costPlanCount = projects.filter((p) => p.projectScope === "COST PLANNING").length;
    return {
      activeCount: active.length, onHoldCount: onHold.length,
      totalProjects: projects.length, totalActiveValue, totalActiveGsf,
      totalValue, totalUnits, costPlanCount,
    };
  }, [projects, gsfTypeFilter, unitsTypeFilter]);

  // Which project types are actually represented in the data — drives both dropdowns.
  // Sorted alphabetically for predictability.
  const projectTypesInUse = useMemo(
    () => [...new Set(projects.map((p) => p.projectType).filter(Boolean))].sort(),
    [projects]
  );

  const statusData = useMemo(() => {
    const counts = {};
    projects.forEach((p) => { const s = p.status || "—"; counts[s] = (counts[s] || 0) + 1; });
    return Object.entries(counts).map(([name, value]) => ({ name, value }));
  }, [projects]);

  // Scope chart now carries BOTH count (bar length) and combined value (end label)
  const scopeData = useMemo(() => {
    const bucket = {};
    projects.forEach((p) => {
      const s = p.projectScope || "—";
      if (!bucket[s]) bucket[s] = { name: s, count: 0, totalValue: 0 };
      bucket[s].count += 1;
      bucket[s].totalValue += parseFloat(p.totalProjectCosts) || 0;
    });
    return Object.values(bucket).sort((a, b) => b.count - a.count);
  }, [projects]);

  const activeProjects = useMemo(
    () => projects.filter((p) => p.status === "ACTIVE").slice(0, 6),
    [projects]
  );

  return (
    <div className="overview-wrap">
      <div className="kpi-grid">
        <KpiCard icon={Briefcase} label="Active Projects" value={kpis.activeCount} sublabel={`of ${kpis.totalProjects} total`} accent="var(--navy)" />
        <KpiCard icon={TrendingUp} label="Active Value" value={fmtCurrency(kpis.totalActiveValue)} sublabel="combined budget" accent="var(--steel)" />
        <KpiCard
          icon={Building2}
          label="Active GSF"
          value={fmtNumber(kpis.totalActiveGsf)}
          sublabel={gsfTypeFilter === "all" ? "gross sq ft" : `gross sq ft · ${gsfTypeFilter.toLowerCase()}`}
          accent="var(--indigo)"
          filter={
            <select className="kpi-filter-select" value={gsfTypeFilter} onChange={(e) => setGsfTypeFilter(e.target.value)} title="Filter by project type">
              <option value="all">All types</option>
              {projectTypesInUse.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
          }
        />
        <KpiCard icon={Calendar} label="On Hold" value={kpis.onHoldCount} sublabel="awaiting client" accent="#c98a3a" />
      </div>
      {/* Secondary KPI row — all-time totals, paler accents so the eye reads
          the primary row first as the "in-flight" snapshot, and this row as
          the "track record" snapshot. */}
      <div className="kpi-grid kpi-grid-secondary">
        <KpiCard icon={LayoutDashboard} label="Total Projects" value={fmtNumber(kpis.totalProjects)} sublabel="all-time on file" accent="var(--steel)" />
        <KpiCard icon={DollarSign} label="Total Project Value" value={fmtCurrency(kpis.totalValue)} sublabel="combined across all projects" accent="#5a8c6f" />
        <KpiCard
          icon={Users}
          label="Total Units"
          value={fmtNumber(kpis.totalUnits)}
          sublabel={unitsTypeFilter === "all" ? "residential + multi-family" : `units · ${unitsTypeFilter.toLowerCase()}`}
          accent="var(--indigo)"
          filter={
            <select className="kpi-filter-select" value={unitsTypeFilter} onChange={(e) => setUnitsTypeFilter(e.target.value)} title="Filter by project type">
              <option value="all">All types</option>
              {projectTypesInUse.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
          }
        />
        <KpiCard icon={ListChecks} label="Cost Plans Provided" value={fmtNumber(kpis.costPlanCount)} sublabel="all-time engagements" accent="var(--steel)" />
      </div>

      <div className="chart-grid">
        <div className="chart-card">
          <div className="chart-header">
            <h3 className="chart-title">Projects by Status</h3>
            <span className="chart-sub">{projects.length} projects</span>
          </div>
          <div style={{ width: "100%", height: 240 }}>
            <ResponsiveContainer>
              <PieChart>
                <Pie data={statusData} dataKey="value" nameKey="name" cx="50%" cy="50%" innerRadius={56} outerRadius={92} paddingAngle={2}>
                  {statusData.map((d, i) => (
                    <Cell key={i} fill={STATUS_COLORS[d.name] || "var(--sky)"} stroke="var(--paper)" strokeWidth={2} />
                  ))}
                </Pie>
                <Tooltip contentStyle={{ background: "var(--white)", border: "1px solid var(--ice)", borderRadius: 4, fontFamily: "Manrope", fontSize: 13 }} formatter={(v, n) => [`${v} projects`, n]} />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="chart-legend">
            {statusData.map((d) => (
              <div key={d.name} className="legend-item">
                <span className="legend-dot" style={{ background: STATUS_COLORS[d.name] || "var(--sky)" }} />
                <span className="legend-label">{d.name}</span>
                <span className="legend-value">{d.value}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="chart-card">
          <div className="chart-header">
            <h3 className="chart-title">By Scope of Work</h3>
            <span className="chart-sub">all-time · count + total value</span>
          </div>
          <div style={{ width: "100%", height: 240 }}>
            <ResponsiveContainer>
              <BarChart data={scopeData} layout="vertical" margin={{ top: 8, right: 96, left: 0, bottom: 8 }}>
                <CartesianGrid horizontal={false} stroke="var(--ice)" />
                <XAxis type="number" tick={{ fontFamily: "Manrope", fontSize: 11, fill: "var(--steel)" }} stroke="var(--ice)" />
                <YAxis type="category" dataKey="name" tick={{ fontFamily: "Manrope", fontSize: 11, fill: "var(--ink)" }} width={140} stroke="var(--ice)" />
                <Tooltip
                  contentStyle={{ background: "var(--white)", border: "1px solid var(--ice)", borderRadius: 4, fontFamily: "Manrope", fontSize: 13 }}
                  cursor={{ fill: "var(--frost)" }}
                  formatter={(_v, _n, item) => [
                    `${item.payload.count} project${item.payload.count === 1 ? "" : "s"} · ${fmtCurrency(item.payload.totalValue)}`,
                    item.payload.name,
                  ]}
                />
                <Bar dataKey="count" radius={[0, 2, 2, 0]}>
                  {scopeData.map((d) => {
                    const c = getScopeColor(d.name);
                    return <Cell key={d.name} fill={c.bg} stroke={c.border} strokeWidth={1} />;
                  })}
                  {/* Total value rendered at the end of each bar so the chart reads
                      both "how many" (bar length) and "how much" (label) at a glance. */}
                  <LabelList
                    dataKey="totalValue"
                    content={(labelProps) => {
                      const { x, y, width, height, value, index } = labelProps;
                      const tone = getScopeColor(scopeData[index] && scopeData[index].name).text;
                      return (
                        <text
                          x={Number(x) + Number(width) + 8}
                          y={Number(y) + Number(height) / 2}
                          dy={4}
                          fontFamily="Manrope"
                          fontSize={10.5}
                          fontWeight={700}
                          letterSpacing="0.02em"
                          fill={tone}
                        >
                          {fmtCurrency(value)}
                        </text>
                      );
                    }}
                  />
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="chart-grid">
        <QSLoadCard
          title="Active Projects by QS"
          sub="live workload"
          unit="active"
          rows={ACTIVE_QS_ROSTER.map((qs) => ({
            name: qs,
            color: qsColor(qs),
            value: projects.filter((p) => p.qs === qs && p.status === "ACTIVE").length,
          }))}
        />
        <QSLoadCard
          title="Total Projects by QS"
          sub="all-time, every status"
          unit="total"
          // Historical view: a retired surveyor still appears while any of
          // their projects remain on file, which is the point of the chart.
          rows={QS_ROSTER
            .filter((qs) => !isRetiredQS(qs) || projects.some((p) => p.qs === qs))
            .map((qs) => ({
              name: isRetiredQS(qs) ? `${qs} (retired)` : qs,
              color: qsColor(qs),
              value: projects.filter((p) => p.qs === qs).length,
            }))}
        />
      </div>

      <div className="active-card">
        <div className="chart-header">
          <h3 className="chart-title">Active Now</h3>
          <span className="chart-sub">{activeProjects.length} projects in flight</span>
        </div>
        {activeProjects.length === 0 ? (
          <div className="empty-state">No active projects. Add one in the Projects tab.</div>
        ) : (
          <div className="active-list">
            {activeProjects.map((p) => (
              <div
                key={p.id}
                className="active-row active-row-clickable"
                onClick={() => onEditProject && onEditProject(p)}
                role="button"
                tabIndex={0}
                onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onEditProject && onEditProject(p); } }}
                title="Open project details"
              >
                <div className="active-row-main">
                  <div className="active-job">#{p.jobNumber}</div>
                  <div className="active-name">{p.projectName}</div>
                  <div className="active-meta">
                    <span>{p.client || "—"}</span>
                    {p.qs && <span className="active-qs">QS: {p.qs}</span>}
                  </div>
                </div>
                <div className="active-row-side">
                  <div className="active-value">{fmtCurrency(p.totalProjectCosts)}</div>
                  <StatusPill status={p.status} />
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      <QSWorkloadSection projects={projects} onProjectUpdate={onProjectUpdate} />
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// QS WORKLOAD SECTION (with Gantt for active mortgage monitoring)
// ──────────────────────────────────────────────────────────────

// Parse YYYY-MM-DD or return null. Avoids new Date(string) timezone surprises.
const parseDate = (s) => {
  if (!s) return null;
  const [y, m, d] = s.split("-").map(Number);
  if (!y || !m || !d) return null;
  return new Date(y, m - 1, d);
};
const daysBetween = (a, b) => Math.round((b - a) / 86400000);
const addDays = (d, n) => { const r = new Date(d); r.setDate(r.getDate() + n); return r; };
const fmtShortDate = (d) => d ? d.toLocaleDateString("en-CA", { month: "short", day: "numeric", year: "numeric" }) : "—";

// Compute monthly tick marks for an axis spanning [start, end]
function monthTicks(start, end) {
  const ticks = [];
  const cursor = new Date(start.getFullYear(), start.getMonth(), 1);
  while (cursor <= end) {
    ticks.push(new Date(cursor));
    cursor.setMonth(cursor.getMonth() + 1);
  }
  return ticks;
}

function GanttChart({ projects, onProjectUpdate }) {
  // projects: filtered list with valid startDate + targetEndDate
  const today = new Date(); today.setHours(0, 0, 0, 0);

  const valid = projects
    .map((p) => ({ ...p, _start: parseDate(p.startDate), _end: parseDate(p.targetEndDate) }))
    .filter((p) => p._start && p._end && p._end >= p._start);

  if (valid.length === 0) {
    return <div className="gantt-empty">No active mortgage monitoring with valid dates.</div>;
  }

  // Compute axis range — earliest start to latest end, padded by ~1 month each side
  const minDate = new Date(Math.min(...valid.map((p) => p._start.getTime())));
  const maxDate = new Date(Math.max(...valid.map((p) => p._end.getTime())));
  // Always include today in the visible range
  const axisStart = addDays(minDate < today ? minDate : today, -20);
  const axisStart1 = new Date(axisStart.getFullYear(), axisStart.getMonth(), 1);
  const axisEnd = addDays(maxDate > today ? maxDate : today, 20);
  const axisEnd1 = new Date(axisEnd.getFullYear(), axisEnd.getMonth() + 1, 0);

  const totalDays = daysBetween(axisStart1, axisEnd1);
  const dayToPercent = (d) => (daysBetween(axisStart1, d) / totalDays) * 100;
  const todayPct = dayToPercent(today);

  const ticks = monthTicks(axisStart1, axisEnd1);

  // Sort by start date so the visual flow is left-to-right
  const sorted = [...valid].sort((a, b) => a._start - b._start);

  return (
    <div className="gantt">
      <div className="gantt-axis">
        <div className="gantt-axis-label-col"></div>
        <div className="gantt-axis-actions-col"></div>
        <div className="gantt-axis-track">
          {ticks.map((t, i) => {
            const pct = dayToPercent(t);
            const isJan = t.getMonth() === 0;
            const showYear = isJan || i === 0;
            return (
              <div key={i} className="gantt-tick" style={{ left: `${pct}%` }}>
                <div className="gantt-tick-line" />
                <div className={`gantt-tick-label ${isJan ? "gantt-tick-year-boundary" : ""}`}>
                  {t.toLocaleDateString("en-CA", { month: "short" })}
                  {showYear && <span className="gantt-tick-year"> '{(t.getFullYear() % 100).toString().padStart(2, "0")}</span>}
                </div>
              </div>
            );
          })}
          {todayPct >= 0 && todayPct <= 100 && (
            <div className="gantt-today" style={{ left: `${todayPct}%` }} title={`Today · ${fmtShortDate(today)}`}>
              <div className="gantt-today-line" />
              <div className="gantt-today-label">Today</div>
            </div>
          )}
        </div>
      </div>

      <div className="gantt-rows">
        {sorted.map((p) => {
          const leftPct = dayToPercent(p._start);
          const rightPct = dayToPercent(p._end);
          const widthPct = Math.max(rightPct - leftPct, 0.5);
          const isOverdue = p.status === "ACTIVE" && p._end < today;
          const isOnHold = p.status === "ON HOLD";
          const isReceived = !!p.awaitingSubmission;
          // Past portion = solid; future portion = lighter
          const elapsedPct = Math.max(0, Math.min(100, ((today - p._start) / (p._end - p._start)) * 100));
          return (
            <div key={p.id} className={`gantt-row ${isReceived ? "gantt-row-received" : ""}`}>
              <div className="gantt-label">
                <div className="gantt-label-name" title={p.projectName}>{p.projectName}</div>
                <div className="gantt-label-meta">
                  <span className="mono">#{p.jobNumber}</span>
                  <span className="gantt-label-client">· {p.client || "—"}</span>
                </div>
              </div>
              <div className="gantt-actions" role="group" aria-label="Draw workflow">
                <button
                  type="button"
                  className={`gantt-action-btn gantt-action-r ${isReceived ? "gantt-action-on" : ""}`}
                  onClick={() => onProjectUpdate && onProjectUpdate(p.id, { awaitingSubmission: true })}
                  title="Received — documents in, awaiting submission to lender"
                  aria-pressed={isReceived}
                >R</button>
                <button
                  type="button"
                  className="gantt-action-btn gantt-action-s"
                  onClick={() => onProjectUpdate && onProjectUpdate(p.id, { awaitingSubmission: false })}
                  disabled={!isReceived}
                  title={isReceived ? "Submitted — clear received flag" : "Nothing to submit"}
                >S</button>
              </div>
              <div className="gantt-track">
                {ticks.map((t, i) => (
                  <div key={i} className="gantt-grid-line" style={{ left: `${dayToPercent(t)}%` }} />
                ))}
                {todayPct >= 0 && todayPct <= 100 && (
                  <div className="gantt-today-line gantt-today-line-row" style={{ left: `${todayPct}%` }} />
                )}
                <div
                  className={`gantt-bar ${isOnHold ? "gantt-bar-hold" : ""} ${isOverdue ? "gantt-bar-overdue" : ""}`}
                  style={(() => {
                    const base = { left: `${leftPct}%`, width: `${widthPct}%` };
                    // On hold and overdue keep their own colours.
                    if (isOnHold || isOverdue) return base;
                    const c = getScopeColor(p.projectScope);
                    return { ...base, background: c.bg, borderColor: c.border };
                  })()}
                  title={`${p.projectName}\n${fmtShortDate(p._start)} → ${fmtShortDate(p._end)}\n${fmtCurrencyFull(p.totalProjectCosts)}${isOverdue ? "\n⚠ OVERDUE" : ""}${isOnHold ? "\n⏸ ON HOLD" : ""}${isReceived ? "\n● AWAITING SUBMISSION" : ""}`}
                >
                  {!isOnHold && (
                    <div
                      className="gantt-bar-fill"
                      style={{
                        width: `${elapsedPct}%`,
                        // The scope's text tone: same hue as the bar, dark
                        // enough to read progress against it.
                        background: (isOnHold || isOverdue) ? undefined : getScopeColor(p.projectScope).text,
                      }}
                    />
                  )}
                </div>
                {(() => {
                  // The date begins one indent in from where the bar
                  // starts, so every date on the chart lines up with its
                  // own start rather than drifting with bar length. It
                  // sits in the track, not the bar, so a short bar cannot
                  // clip it.
                  const tone = getScopeColor(p.projectScope).text;
                  return (
                    <span
                      className="gantt-bar-date"
                      style={{
                        left: `${leftPct}%`,
                        color: (isOnHold || isOverdue) ? undefined : tone,
                      }}
                    >
                      {isOverdue && <AlertCircle size={10} />}
                      {fmtShortDate(p._end)}
                    </span>
                  );
                })()}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function CompletedList({ projects }) {
  if (projects.length === 0) {
    return <div className="gantt-empty">No completed projects on record.</div>;
  }
  const sorted = [...projects].sort((a, b) => (b.actualEndDate || "").localeCompare(a.actualEndDate || ""));
  return (
    <ul className="completed-list">
      {sorted.map((p) => (
        <li key={p.id} className="completed-row">
          <div className="completed-row-main">
            <div className="completed-job mono">#{p.jobNumber}</div>
            <div className="completed-name">{p.projectName}</div>
            <div className="completed-meta">
              <span className="tag">{p.projectScope}</span>
              <span>{p.client || "—"}</span>
            </div>
          </div>
          <div className="completed-row-side">
            <div className="completed-end">
              <span className="completed-end-label">Completed</span>
              <span className="completed-end-date">{p.actualEndDate || "—"}</span>
            </div>
            <div className="completed-value mono">{fmtCurrency(p.totalProjectCosts)}</div>
          </div>
        </li>
      ))}
    </ul>
  );
}

function QSWorkloadCard({ qsName, projects, onProjectUpdate }) {
  const [tab, setTab] = useState("active");

  const myProjects = useMemo(() => projects.filter((p) => p.qs === qsName), [projects, qsName]);

  // Active view: only mortgage monitoring + statuses ACTIVE/ON HOLD
  const activeMonitoring = useMemo(
    () => myProjects.filter((p) => WORKLOAD_SCOPES.includes(p.projectScope) && (p.status === "ACTIVE" || p.status === "ON HOLD")),
    [myProjects]
  );
  // Completed view: any scope, status COMPLETED
  const completed = useMemo(
    () => myProjects.filter((p) => p.status === "COMPLETED"),
    [myProjects]
  );
  // Side stats
  const totalActive = myProjects.filter((p) => p.status === "ACTIVE").length;
  const totalOnHold = myProjects.filter((p) => p.status === "ON HOLD").length;

  return (
    <div className="qs-card">
      <div className="qs-card-header">
        <div className="qs-avatar">{qsInitials(qsName)}</div>
        <div className="qs-id">
          <div className="qs-name">{qsName}</div>
          <div className="qs-summary">
            <span>{totalActive} active</span>
            {totalOnHold > 0 && <span className="qs-summary-hold">· {totalOnHold} on hold</span>}
            <span>· {completed.length} completed</span>
            <span className="qs-summary-sep">·</span>
            <span><b>{activeMonitoring.length}</b> mortgage monitoring</span>
          </div>
        </div>
        <div className="qs-toggle" role="tablist">
          <button
            className={`qs-toggle-btn ${tab === "active" ? "qs-toggle-btn-on" : ""}`}
            onClick={() => setTab("active")}
            role="tab"
            aria-selected={tab === "active"}
          >
            Active
          </button>
          <button
            className={`qs-toggle-btn ${tab === "completed" ? "qs-toggle-btn-on" : ""}`}
            onClick={() => setTab("completed")}
            role="tab"
            aria-selected={tab === "completed"}
          >
            <ListChecks size={11} /> Completed
          </button>
        </div>
      </div>

      <div className="qs-card-body">
        {tab === "active"
          ? <GanttChart projects={activeMonitoring} onProjectUpdate={onProjectUpdate} />
          : <CompletedList projects={completed} />}
      </div>
    </div>
  );
}

// Track-and-fill bar chart: one row per QS, the track sized to the busiest
// so the comparison is against the heaviest load rather than the card width.
function QSLoadCard({ title, sub, rows, unit }) {
  const max = Math.max(1, ...rows.map((r) => r.value));
  const total = rows.reduce((sum, r) => sum + r.value, 0);
  return (
    <div className="chart-card">
      <div className="chart-header">
        <h3 className="chart-title">{title}</h3>
        <span className="chart-sub">{sub}</span>
      </div>
      <div className="qsbar-list">
        {rows.map((r) => {
          // Bar length compares against the busiest person; the badge reports
          // share of the whole, which is the figure worth reading off a
          // workload chart.
          const pct = (r.value / max) * 100;
          const share = total > 0 ? Math.round((r.value / total) * 100) : 0;
          return (
            <div key={r.name} className="qsbar-row">
              <span className="qsbar-name" title={r.name}>{r.name}</span>
              <span className="qsbar-dot" style={{ background: r.color }} />
              <div className="qsbar-track">
                <div className="qsbar-fill" style={{ width: `${pct}%`, background: r.color }} />
                {r.value > 0 && (
                  <span
                    className="qsbar-badge"
                    style={{ left: `${pct}%`, background: r.color }}
                    title={`${r.value} of ${total} — ${share}%`}
                  >
                    <span className="qsbar-badge-text">{share}%</span>
                  </span>
                )}
              </div>
              <span className="qsbar-total">{r.value}{unit ? ` ${unit}` : ""}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function QSWorkloadSection({ projects, onProjectUpdate }) {
  return (
    <div className="qs-section">
      <div className="chart-header" style={{ marginBottom: 20 }}>
        <h3 className="chart-title">QS Workload</h3>
        <span className="chart-sub">monitoring, estimating and depreciation work by quantity surveyor</span>
        <div className="qs-legend">
          {WORKLOAD_SCOPES.map((sc) => {
            const c = getScopeColor(sc);
            return (
              <span key={sc} className="qs-legend-item">
                <span className="qs-legend-dot" style={{ background: c.bg, borderColor: c.border }} />
                {sc}
              </span>
            );
          })}
        </div>
      </div>
      <div className="qs-cards">
        {ACTIVE_QS_ROSTER.map((qs) => (
          <QSWorkloadCard key={qs} qsName={qs} projects={projects} onProjectUpdate={onProjectUpdate} />
        ))}
      </div>
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// PROJECT FORM
// ──────────────────────────────────────────────────────────────
// Minimal organisation form used inside the project form. Deliberately short:
// name and type are enough to create a usable register entry, and the full
// record can be completed later on the Lenders or Developers tab.
// Full contact capture, used from the project form so a new person can be
// recorded without leaving the project. Only the name is required — the rest
// is often not known at the point of first contact.
function NewContactForm({ developerName, onAdd, onCancel }) {
  const [f, setF] = useState({ name: "", title: "", email: "", phone: "", cellPhone: "", notes: "" });
  const set = (k, v) => setF((prev) => ({ ...prev, [k]: v }));

  const add = () => {
    if (!f.name.trim()) return;
    onAdd({
      id: uid(),
      name: f.name.trim(),
      title: f.title.trim(),
      email: f.email.trim(),
      phone: f.phone.trim(),
      cellPhone: f.cellPhone.trim(),
      notes: f.notes.trim(),
      comments: [],
    });
  };

  return (
    <div className="org-draft">
      <div className="org-draft-head">
        <span className="org-draft-title">New contact</span>
        <span className="org-draft-note">Added to {developerName} when you save this project.</span>
      </div>
      <div className="form-grid form-grid-2">
        <Field label="Name" required>
          <input className="input" autoFocus value={f.name} onChange={(e) => set("name", e.target.value)}
            placeholder="Full name" />
        </Field>
        <Field label="Title">
          <input className="input" value={f.title} onChange={(e) => set("title", e.target.value)}
            placeholder="e.g. Development Manager" />
        </Field>
        <Field label="Email">
          <input className="input" type="email" value={f.email} onChange={(e) => set("email", e.target.value)} />
        </Field>
        <Field label="Phone">
          <input className="input" type="tel" value={f.phone} onChange={(e) => set("phone", e.target.value)}
            placeholder="250-555-0100" />
        </Field>
        <Field label="Cell">
          <input className="input" type="tel" value={f.cellPhone} onChange={(e) => set("cellPhone", e.target.value)} />
        </Field>
        <Field label="Notes">
          <input className="input" value={f.notes} onChange={(e) => set("notes", e.target.value)} />
        </Field>
      </div>
      <div className="org-draft-foot">
        <button type="button" className="btn btn-ghost" onClick={onCancel}>Cancel</button>
        <button type="button" className="btn btn-primary" disabled={!f.name.trim()} onClick={add}>
          <Plus size={14} /> Add contact
        </button>
      </div>
    </div>
  );
}

function NewOrgForm({ kind, onAdd, onCancel }) {
  const isLender = kind === "lender";
  const [name, setName] = useState("");
  const [type, setType] = useState(isLender ? "BANK" : "DEVELOPER");
  const [contact, setContact] = useState("");
  const [notes, setNotes] = useState("");
  const types = isLender
    ? ["BANK", "CREDIT UNION", "PRIVATE", "MIC", "CMHC", "OTHER"]
    : ["DEVELOPER", "OWNER-BUILDER", "BUILDER", "NON-PROFIT", "OTHER"];

  const add = () => {
    if (!name.trim()) return;
    onAdd({
      id: uid(),
      name: name.trim(),
      type,
      notes: notes.trim(),
      staff: contact.trim()
        ? [{ id: uid(), name: contact.trim(), title: "", email: "", phone: "", notes: "", comments: [] }]
        : [],
    });
  };

  return (
    <div className="org-draft">
      <div className="org-draft-head">
        <span className="org-draft-title">New {isLender ? "lender" : "developer"}</span>
        <span className="org-draft-note">
          Added to the {isLender ? "Lenders" : "Developers"} register when you save this project.
        </span>
      </div>
      <div className="form-grid form-grid-2">
        <Field label="Name" required>
          <input className="input" autoFocus value={name} onChange={(e) => setName(e.target.value)}
            placeholder={isLender ? "e.g. Vancity" : "e.g. Aragon Properties"} />
        </Field>
        <Field label="Type">
          <select className="input" value={type} onChange={(e) => setType(e.target.value)}>
            {types.map((t) => <option key={t} value={t}>{t}</option>)}
          </select>
        </Field>
        <Field label={isLender ? "File manager (optional)" : "Primary contact (optional)"}>
          <input className="input" value={contact} onChange={(e) => setContact(e.target.value)}
            placeholder="Full name" />
        </Field>
        <Field label="Notes (optional)">
          <input className="input" value={notes} onChange={(e) => setNotes(e.target.value)} />
        </Field>
      </div>
      <div className="org-draft-foot">
        <button type="button" className="btn btn-ghost" onClick={onCancel}>Cancel</button>
        <button type="button" className="btn btn-primary" disabled={!name.trim()} onClick={add}>
          <Plus size={14} /> Add {isLender ? "lender" : "developer"}
        </button>
      </div>
    </div>
  );
}

function ProjectForm({ project, lenders = [], developers = [], onSave, onCancel }) {
  // Organisations added inline, held until the project is saved.
  const [newOrgs, setNewOrgs] = useState({ lender: null, developer: null });
  const [orgDraft, setOrgDraft] = useState(null); // { kind } while the mini-form is open
  const allLenders = newOrgs.lender ? [...lenders, newOrgs.lender] : lenders;
  const allDevelopers = useMemo(() => {
    let list = newOrgs.developer ? [...developers, newOrgs.developer] : developers;
    // A contact added moments ago must appear in the picker straight away,
    // even though it is not written to the register until save.
    if (newOrgs.contact) {
      list = list.map((d) => (d.id === newOrgs.contact.developerId
        ? { ...d, staff: [...(d.staff || []), newOrgs.contact.person] }
        : d));
    }
    return list;
  }, [developers, newOrgs]);
  const [form, setForm] = useState(project || {
    id: uid(), flag: "P", jobNumber: "", projectName: "", address: "", year: new Date().getFullYear(),
    startDate: "", targetEndDate: "", actualEndDate: "",
    lat: "", lng: "",
    municipality: "", region: "", qs: "", status: "ACTIVE",
    client: "", contact: "", developer: "",
    projectScope: "COST PLANNING", projectType: "COMMERCIAL",
    sfParking: 0, institutional: 0, sfCommercial: 0, sfResidential: 0, sfGross: 0,
    storys: 0, units: 0, lots: 0,
    landCost: 0, softCost: 0, financeCost: 0, hardCost: 0, contingency: 0,
    gstCosts: 0, cmhcCosts: 0, totalProjectCosts: 0, costPerSf: 0,
    lenderId: "", lenderName: "", fileManagerId: "", fileManagerName: "",
    loanAmount: 0, interestRate: "",
  });
  const set = (k, v) => setForm((f) => ({ ...f, [k]: v }));

  useEffect(() => {
    const total = (parseFloat(form.landCost) || 0) + (parseFloat(form.softCost) || 0) + (parseFloat(form.financeCost) || 0) +
      (parseFloat(form.hardCost) || 0) + (parseFloat(form.contingency) || 0) + (parseFloat(form.gstCosts) || 0) + (parseFloat(form.cmhcCosts) || 0);
    const sf = parseFloat(form.sfGross) || 0;
    const cps = sf > 0 ? (parseFloat(form.hardCost) || 0) / sf : 0;
    setForm((f) => ({ ...f, totalProjectCosts: total, costPerSf: cps }));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [form.landCost, form.softCost, form.financeCost, form.hardCost, form.contingency, form.gstCosts, form.cmhcCosts, form.sfGross]);

  const submit = () => {
    if (!form.projectName || !form.jobNumber) { alert("Job # and Project Name are required"); return; }
    // Client is no longer typed in. On a development instruction it is the
    // developer; on a monitoring instruction it is the lender. Anything
    // already recorded is left alone.
    const derivedClient = form.client || form.developer || form.lenderName || "";
    onSave({ ...form, client: derivedClient }, newOrgs);
  };

  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-header">
          <h2 className="modal-title">{project ? "Edit Project" : "New Project"}</h2>
          <button className="icon-btn" onClick={onCancel}><X size={18} /></button>
        </div>
        <div className="modal-body">
          <div className="form-section">
            <div className="form-section-title">Identification</div>
            <div className="form-grid form-grid-3">
              <Field label="Job #" required><input className="input" type="number" value={form.jobNumber} onChange={(e) => set("jobNumber", e.target.value)} /></Field>
              <Field label="Year"><input className="input" type="number" value={form.year} onChange={(e) => set("year", parseInt(e.target.value) || "")} /></Field>
              <Field label="Flag"><select className="input" value={form.flag} onChange={(e) => set("flag", e.target.value)}><option value="P">P (Project)</option><option value="O">O (Office)</option></select></Field>
              <Field label="Project Name" required full><input className="input" value={form.projectName} onChange={(e) => set("projectName", e.target.value)} /></Field>
              <Field label="Address" full><input className="input" value={form.address} onChange={(e) => set("address", e.target.value)} /></Field>
            </div>
          </div>
          <div className="form-section">
            <div className="form-section-title">Location</div>
            <div className="form-grid form-grid-2">
              <Field label="Municipality"><input className="input" value={form.municipality} onChange={(e) => set("municipality", e.target.value)} /></Field>
              <Field label="Region"><input className="input" value={form.region} onChange={(e) => set("region", e.target.value)} /></Field>
            </div>
          </div>
          <div className="form-section">
            <div className="form-section-title">People</div>
            <div className="form-grid form-grid-3">
              <Field label="QS (Primary)">
                <select className="input" value={form.qs} onChange={(e) => set("qs", e.target.value)}>
                  <option value="">— Unassigned —</option>
                  {ACTIVE_QS_ROSTER.map((name) => <option key={name} value={name}>{name}</option>)}
                  {/* Keep a retired surveyor selectable on a record that
                      already carries their name, so editing an old project
                      does not quietly reassign it. */}
                  {isRetiredQS(form.qs) && (
                    <option value={form.qs}>{form.qs} — retired</option>
                  )}
                </select>
              </Field>
              <Field label="Developer" full>
                <div className="org-pick-row">
                  <select className="input" value={form.developerId || ""} onChange={(e) => {
                    const picked = allDevelopers.find((d) => d.id === e.target.value);
                    setForm((f) => ({
                      ...f,
                      developerId: e.target.value,
                      developer: picked ? picked.name : "",
                    }));
                  }}>
                    <option value="">{form.developer && !form.developerId ? form.developer : "— None —"}</option>
                    {allDevelopers.map((d) => <option key={d.id} value={d.id}>{d.name}</option>)}
                  </select>
                  <button type="button" className="org-add-btn"
                    onClick={() => setOrgDraft({ kind: "developer" })}>+ New developer</button>
                </div>
              </Field>
              <Field label="Developer contact" full>
                <div className="org-pick-row">
                  <select
                    className="input"
                    value={form.contactId || ""}
                    disabled={!form.developerId}
                    onChange={(e) => {
                      const staff = (allDevelopers.find((d) => d.id === form.developerId)?.staff) || [];
                      const person = staff.find((c) => c.id === e.target.value);
                      setForm((f) => ({
                        ...f,
                        contactId: e.target.value,
                        // The project keeps the name too, so historical
                        // records still read if the contact later leaves.
                        contact: person ? person.name : f.contact,
                      }));
                    }}
                  >
                    <option value="">{form.developerId ? "— None —" : "Select a developer first"}</option>
                    {((allDevelopers.find((d) => d.id === form.developerId)?.staff) || []).map((c) => (
                      <option key={c.id} value={c.id}>{c.name}{c.title ? ` — ${c.title}` : ""}</option>
                    ))}
                  </select>
                  <button
                    type="button"
                    className="org-add-btn"
                    disabled={!form.developerId}
                    onClick={() => setOrgDraft({ kind: "contact" })}
                  >+ New contact</button>
                </div>
              </Field>
            </div>
          </div>
          <div className="form-section">
            <div className="form-section-title org-title-row">
              <span>Finance</span>
              <button type="button" className="org-add-btn"
                onClick={() => setOrgDraft({ kind: "lender" })}>+ New lender</button>
            </div>
            <div className="form-grid form-grid-2">
              <Field label="Lender">
                <select className="input" value={form.lenderId || ""} onChange={(e) => {
                  const picked = allLenders.find((l) => l.id === e.target.value);
                  setForm((f) => ({
                    ...f,
                    lenderId: e.target.value,
                    lenderName: picked ? picked.name : "",
                    // The file manager belongs to a lender, so changing the
                    // lender clears a contact who no longer works there.
                    fileManagerId: "",
                    fileManagerName: "",
                  }));
                }}>
                  <option value="">— None —</option>
                  {allLenders.map((l) => <option key={l.id} value={l.id}>{l.name}</option>)}
                </select>
              </Field>
              <Field label="File Manager">
                <select className="input" value={form.fileManagerId || ""} disabled={!form.lenderId}
                  onChange={(e) => {
                    const lender = allLenders.find((l) => l.id === form.lenderId);
                    const staff = (lender?.staff || []).find((p) => p.id === e.target.value);
                    setForm((f) => ({
                      ...f,
                      fileManagerId: e.target.value,
                      fileManagerName: staff ? staff.name : "",
                    }));
                  }}>
                  <option value="">{form.lenderId ? "— None —" : "Select a lender first"}</option>
                  {(allLenders.find((l) => l.id === form.lenderId)?.staff || []).map((p) => (
                    <option key={p.id} value={p.id}>{p.name}{p.title ? ` — ${p.title}` : ""}</option>
                  ))}
                </select>
              </Field>
              <Field label="Loan Amount">
                <input className="input" type="number" value={form.loanAmount ?? 0}
                  onChange={(e) => set("loanAmount", parseFloat(e.target.value) || 0)} />
              </Field>
              <Field label="Interest Rate (%)">
                <input className="input" type="number" step="0.01" value={form.interestRate ?? ""}
                  placeholder="e.g. 7.25"
                  onChange={(e) => set("interestRate", e.target.value)} />
              </Field>
            </div>
          </div>

          <div className="form-section">
            <div className="form-section-title">Schedule</div>
            <div className="form-grid form-grid-3">
              <Field label="Start Date"><input className="input" type="date" value={form.startDate} onChange={(e) => set("startDate", e.target.value)} /></Field>
              <Field label="Target End Date"><input className="input" type="date" value={form.targetEndDate} onChange={(e) => set("targetEndDate", e.target.value)} /></Field>
              <Field label="Actual End Date"><input className="input" type="date" value={form.actualEndDate} onChange={(e) => set("actualEndDate", e.target.value)} /></Field>
            </div>
          </div>
          <div className="form-section">
            <div className="form-section-title">Map Coordinates <span style={{fontWeight:400, color:"var(--steel)", textTransform:"none", letterSpacing:0, fontStyle:"italic", marginLeft:8}}>— paste from Google Maps to plot on the Map tab</span></div>
            <div className="form-grid form-grid-2">
              <Field label="Latitude"><input className="input" type="number" step="any" placeholder="e.g. 48.4327" value={form.lat} onChange={(e) => set("lat", e.target.value)} /></Field>
              <Field label="Longitude"><input className="input" type="number" step="any" placeholder="e.g. -123.3531" value={form.lng} onChange={(e) => set("lng", e.target.value)} /></Field>
            </div>
          </div>
          <div className="form-section">
            <div className="form-section-title">Classification</div>
            <div className="form-grid form-grid-3">
              <Field label="Status"><select className="input" value={form.status} onChange={(e) => set("status", e.target.value)}>{STATUS_OPTIONS.map((s) => <option key={s}>{s}</option>)}</select></Field>
              <Field label="Scope"><select className="input" value={form.projectScope} onChange={(e) => set("projectScope", e.target.value)}>{SCOPE_OPTIONS.map((s) => <option key={s}>{s}</option>)}</select></Field>
              <Field label="Type"><select className="input" value={form.projectType} onChange={(e) => set("projectType", e.target.value)}>{TYPE_OPTIONS.map((s) => <option key={s}>{s}</option>)}</select></Field>
            </div>
          </div>
          <div className="form-section">
            <div className="form-section-title">Areas (sq ft)</div>
            <div className="form-grid form-grid-4">
              <Field label="Parking SF"><input className="input" type="number" value={form.sfParking} onChange={(e) => set("sfParking", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Institutional"><input className="input" type="number" value={form.institutional} onChange={(e) => set("institutional", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Commercial SF"><input className="input" type="number" value={form.sfCommercial} onChange={(e) => set("sfCommercial", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Residential SF"><input className="input" type="number" value={form.sfResidential} onChange={(e) => set("sfResidential", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Gross SF"><input className="input" type="number" value={form.sfGross} onChange={(e) => set("sfGross", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Storys"><input className="input" type="number" value={form.storys} onChange={(e) => set("storys", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Units"><input className="input" type="number" value={form.units} onChange={(e) => set("units", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Lots"><input className="input" type="number" value={form.lots} onChange={(e) => set("lots", parseFloat(e.target.value) || 0)} /></Field>
            </div>
          </div>
          <div className="form-section">
            <div className="form-section-title">Project Costs (auto-totals)</div>
            <div className="form-grid form-grid-4">
              <Field label="Land"><input className="input" type="number" value={form.landCost} onChange={(e) => set("landCost", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Soft"><input className="input" type="number" value={form.softCost} onChange={(e) => set("softCost", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Finance"><input className="input" type="number" value={form.financeCost} onChange={(e) => set("financeCost", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Hard"><input className="input" type="number" value={form.hardCost} onChange={(e) => set("hardCost", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Contingency"><input className="input" type="number" value={form.contingency} onChange={(e) => set("contingency", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="GST"><input className="input" type="number" value={form.gstCosts} onChange={(e) => set("gstCosts", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="CMHC"><input className="input" type="number" value={form.cmhcCosts} onChange={(e) => set("cmhcCosts", parseFloat(e.target.value) || 0)} /></Field>
              <Field label="Cost / SF (HC)"><input className="input input-readonly" value={form.costPerSf?.toFixed(2) || "0.00"} readOnly /></Field>
            </div>
            <div className="total-row">
              <span className="total-label">Total Project Costs</span>
              <span className="total-value">{fmtCurrencyFull(form.totalProjectCosts)}</span>
            </div>
          </div>
        </div>
        {orgDraft && orgDraft.kind === "contact" && (
          <NewContactForm
            developerName={(allDevelopers.find((d) => d.id === form.developerId) || {}).name || "this developer"}
            onCancel={() => setOrgDraft(null)}
            onAdd={(contact) => {
              setNewOrgs((n) => ({ ...n, contact: { developerId: form.developerId, person: contact } }));
              setForm((f) => ({ ...f, contactId: contact.id, contact: contact.name }));
              setOrgDraft(null);
            }}
          />
        )}
        {orgDraft && orgDraft.kind !== "contact" && (
          <NewOrgForm
            kind={orgDraft.kind}
            onCancel={() => setOrgDraft(null)}
            onAdd={(org) => {
              setNewOrgs((n) => ({ ...n, [orgDraft.kind]: org }));
              if (orgDraft.kind === "lender") {
                setForm((f) => ({ ...f, lenderId: org.id, lenderName: org.name, fileManagerId: "", fileManagerName: "" }));
              } else {
                setForm((f) => ({ ...f, developerId: org.id, developer: org.name }));
              }
              setOrgDraft(null);
            }}
          />
        )}
        <div className="modal-footer">
          <button className="btn btn-ghost" onClick={onCancel}>Cancel</button>
          <button className="btn btn-primary" onClick={submit}><Save size={14} /> {project ? "Save changes" : "Add project"}</button>
        </div>
      </div>
    </div>
  );
}

// ──────────────────────────────────────────────────────────────
// PROJECT DETAIL & TABLE
