// ── HERO ───────────────────────────────────────────────────────────────────
const LibraryHero = ({ projects, title, subtitleNoun, valueLabel = 'Total construction value' }) => {
  const totalValue = projects.reduce((s, p) => s + projectTotal(p), 0);
  const weightedPerSfGross = (() => {
    const tg = projects.reduce((s, p) => s + (p.sfGross || 0), 0);
    return tg > 0 ? totalValue / tg : 0;
  })();
  const weightedPerSfNet = (() => {
    const tn = projects.reduce((s, p) => s + (p.sfNet || 0), 0);
    return tn > 0 ? totalValue / tn : 0;
  })();

  return (
    <div style={{ maxWidth: 1400, margin: '0 auto', padding: '32px 32px 16px' }}>
      <div style={{
        display: 'flex', alignItems: 'baseline', justifyContent: 'space-between',
        marginBottom: 22, flexWrap: 'wrap', gap: 12,
      }}>
        <h1 className="font-display" style={{
          fontSize: 30, color: C.navy, letterSpacing: '-0.015em',
          margin: 0,
        }}>
          {title}
        </h1>
        <span className="font-sans tracker" style={{ fontSize: 11, color: C.steel }}>
          {projects.length} {projects.length === 1 ? subtitleNoun : `${subtitleNoun}s`}
        </span>
      </div>

      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
        gap: 16,
      }}>
        <KpiCard
          icon={Building2}
          label="Projects"
          value={projects.length}
          sublabel={subtitleNoun + (projects.length === 1 ? '' : 's')}
          accent={C.navy}
        />
        <KpiCard
          icon={BarChart3}
          label={valueLabel}
          value={projects.length === 0 ? <span style={{ fontStyle: 'italic', color: C.sky }}>—</span> : fmtM(totalValue)}
          sublabel="combined budget"
          accent={C.steel}
        />
        <KpiCard
          icon={TrendingUp}
          label="Weighted $/sf gross"
          value={weightedPerSfGross === 0 ? <span style={{ fontStyle: 'italic', color: C.sky }}>—</span> : fmtPerSf(weightedPerSfGross)}
          sublabel="per gross square foot"
          accent={C.indigo}
        />
        <KpiCard
          icon={Activity}
          label="Weighted $/sf net"
          value={weightedPerSfNet === 0 ? <span style={{ fontStyle: 'italic', color: C.sky }}>—</span> : fmtPerSf(weightedPerSfNet)}
          sublabel="per net square foot"
          accent="#5a8c6f"
        />
      </div>
    </div>
  );
};

