// ── PROJECT ROW (LIBRARY) ──────────────────────────────────────────────────
const ProjectRow = ({ project, expanded, selected, onToggleSelect, onToggleExpand, onDelete, onAddBudget, subTab }) => {
  const total = projectTotal(project);
  const isActive = subTab === 'active';

  // Which budget slot, if any, is missing? Summary is required at creation, so this is
  // almost always 'detailed' — but the code stays symmetric in case of legacy data.
  const hasSummary = Array.isArray(project.summaryLineItems) && project.summaryLineItems.length > 0;
  const hasDet = hasDetailed(project);
  const missingSlot = !hasSummary ? 'summary' : (!hasDet ? 'detailed' : null);

  // Date column content: completion date for completed, "added" month for active
  return (
    <>
      <div
        className="row-hover"
        style={{
          display: 'grid',
          gridTemplateColumns: LIBRARY_COLUMNS,
          gap: 14,
          padding: '16px 24px',
          borderBottom: `1px solid ${C.frost}`,
          alignItems: 'center',
          transition: 'background 140ms ease',
          background: selected ? C.frost : 'transparent',
        }}
      >
        {/* Checkbox: only for completed (compare is completed-only) */}
        {isActive ? (
          <span />
        ) : (
          <input
            type="checkbox"
            checked={selected}
            onChange={() => onToggleSelect(project.id)}
            onClick={(e) => e.stopPropagation()}
          />
        )}
        <span className="font-sans tnum" style={{ fontSize: 12, color: C.steel }}>{project.number}</span>
        <button
          onClick={() => onToggleExpand(project.id)}
          style={{ background: 'none', border: 'none', textAlign: 'left', padding: 0, cursor: 'pointer',
            display: 'flex', alignItems: 'center', gap: 8, minWidth: 0, overflow: 'hidden' }}
        >
          {expanded ? <ChevronDown size={14} color={C.steel} strokeWidth={1.6} /> : <ChevronRight size={14} color={C.steel} strokeWidth={1.6} />}
          <span
            className="font-sans"
            style={{
              fontSize: 14, color: C.ink, fontWeight: 500,
              whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis',
            }}
            title={project.name}
          >{project.name}</span>
        </button>
        <span className="font-sans" style={{ fontSize: 12, color: C.navy }}>{project.type}</span>
        <span className="font-sans" style={{ fontSize: 12, color: C.navy }}>{project.municipality}</span>
        <span className="font-sans tnum" style={{ fontSize: 13, color: C.ink, textAlign: 'right' }}>{fmtSf(project.sfGross)}</span>
        <span className="font-sans tnum" style={{ fontSize: 13, color: C.ink, textAlign: 'right' }}>{fmtSf(project.sfNet)}</span>
        <span className="font-sans tnum" style={{ fontSize: 13, color: C.ink, textAlign: 'right', fontWeight: 500 }}>{fmtM(total)}</span>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, justifySelf: 'end' }}>
        {missingSlot && (
          <button
            onClick={(e) => { e.stopPropagation(); onAddBudget(project.id, missingSlot); }}
            className="font-sans tracker"
            style={{
              padding: '4px 7px',
              background: C.greenBg,
              border: `1px solid ${C.greenBd}`,
              color: C.green,
              fontSize: 8,
              lineHeight: 1.25,
              letterSpacing: '0.06em',
              cursor: 'pointer',
              display: 'inline-flex',
              alignItems: 'center',
              gap: 4,
              textAlign: 'left',
              transition: 'all 140ms ease',
            }}
            onMouseEnter={(e) => { e.currentTarget.style.background = C.green; e.currentTarget.style.color = C.white; }}
            onMouseLeave={(e) => { e.currentTarget.style.background = C.greenBg; e.currentTarget.style.color = C.green; }}
          >
            <Plus size={9} strokeWidth={2} style={{ flexShrink: 0 }} />
            <span>Add {missingSlot}<br />budget</span>
          </button>
        )}
        <button
          onClick={() => onDelete(project.id)}
          style={{ background: 'none', border: 'none', cursor: 'pointer', color: C.sky, padding: 6 }}
          aria-label="Delete project"
        >
          <Trash2 size={14} strokeWidth={1.5} />
        </button>
        </div>
      </div>


    </>
  );
};

