// ── HELPERS ─────────────────────────────────────────────────────────────────
const todayISO = () => new Date().toISOString().slice(0, 10);
const uid = () => Date.now() + Math.floor(Math.random() * 1000);

// Steps arrive as either a plain string or { text, substeps }. Normalising once
// on load means the editor only ever deals with one shape.
const normaliseSteps = (steps) => (steps || []).map((s) =>
  typeof s === 'string' ? { text: s, substeps: [] } : { text: s.text || '', substeps: s.substeps || [] });

const normaliseTemplate = (t) => ({
  ...t,
  steps: normaliseSteps(t.steps),
  meta: t.meta || {
    owner: '', department: catLabel(t.cat), jurisdiction: 'British Columbia, Canada',
    effective: todayISO(), review: '', reference: '',
  },
  notes: t.notes || '',
});

const isDue = (t) => {
  const d = t.meta?.review;
  if (!d || !/^\d{4}-\d{2}-\d{2}$/.test(d)) return false;
  return d <= todayISO();
};

const STORE_KEY = 'beacon-sop:templates';
const sopStore = {
  async load() {
    try {
      const r = await window.storage.get(STORE_KEY);
      return r && r.value ? JSON.parse(r.value) : null;
    } catch (err) { return null; }
  },
  async save(value) {
    try { await window.storage.set(STORE_KEY, JSON.stringify(value)); }
    catch (err) { console.warn('Could not save SOP library:', err); }
  },
};

// ── AUTO-SIZING TEXTAREA ────────────────────────────────────────────────────
// The HTML version called autoResize() by hand after every render. A ref does
// the same job without the bookkeeping.
function GrowTextarea({ value, onChange, className, ...rest }) {
  const ref = useRef(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.style.height = 'auto';
    el.style.height = el.scrollHeight + 'px';
  }, [value]);
  return (
    <textarea ref={ref} className={className} value={value}
      onChange={(e) => onChange(e.target.value)} {...rest} />
  );
}

// ── ROOT ────────────────────────────────────────────────────────────────────
function SOPLibraryApp({ firm, onSummary, onExit }) {
  const [templates, setTemplates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab] = useState('library');        // 'library' | 'ref'
  const [cat, setCat] = useState(null);
  const [query, setQuery] = useState('');
  const [openId, setOpenId] = useState(null);
  const [addingCat, setAddingCat] = useState(null);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    let mounted = true;
    sopStore.load().then((stored) => {
      if (!mounted) return;
      setTemplates((stored && stored.length ? stored : BASE_TEMPLATES).map(normaliseTemplate));
      setLoading(false);
    });
    return () => { mounted = false; };
  }, []);

  const persist = (next) => { setTemplates(next); sopStore.save(next); };

  // Roll up for the practice tile on the dashboard.
  useEffect(() => {
    if (loading || typeof onSummary !== 'function') return;
    onSummary({
      docCount: templates.length,
      dueReview: templates.filter(isDue).length,
      lastReviewed: todayISO(),
    });
  }, [loading, templates]); // eslint-disable-line react-hooks/exhaustive-deps

  const open = openId != null ? templates.find((t) => t.id === openId) : null;

  const visible = useMemo(() => {
    const q = query.trim().toLowerCase();
    return templates.filter((t) =>
      (!cat || t.cat === cat) &&
      (!q || t.title.toLowerCase().includes(q) || t.desc.toLowerCase().includes(q)));
  }, [templates, cat, query]);

  const patchOpen = (patch) =>
    persist(templates.map((t) => (t.id === openId ? { ...t, ...patch } : t)));

  const patchStep = (i, text) =>
    patchOpen({ steps: open.steps.map((s, si) => (si === i ? { ...s, text } : s)) });

  const patchSub = (i, si, text) =>
    patchOpen({
      steps: open.steps.map((s, x) => x !== i ? s
        : { ...s, substeps: s.substeps.map((v, y) => (y === si ? text : v)) }),
    });

  const addStep = () => patchOpen({ steps: [...open.steps, { text: '', substeps: [] }] });
  const addSub = (i) => patchOpen({
    steps: open.steps.map((s, x) => (x === i ? { ...s, substeps: [...s.substeps, ''] } : s)),
  });
  const removeSub = (i, si) => patchOpen({
    steps: open.steps.map((s, x) => (x === i ? { ...s, substeps: s.substeps.filter((_, y) => y !== si) } : s)),
  });
  const removeStep = (i) => patchOpen({ steps: open.steps.filter((_, x) => x !== i) });

  const createSOP = (title, desc, compliance) => {
    const t = normaliseTemplate({
      id: uid(), cat: addingCat, title, icon: '📋',
      desc: desc || 'No description provided.',
      compliance: compliance || 'Review applicable BC legislation before implementing this SOP.',
      steps: [
        'Define the purpose and scope of this procedure',
        'List the roles and responsibilities involved',
        'Document each step of the procedure in sequence',
        'Define quality control checkpoints',
        'Record any forms, tools, or references required',
      ],
    });
    persist([...templates, t]);
    setAddingCat(null);
    setCat(t.cat);
    setTab('library');
  };

  const markSaved = () => { setSaved(true); setTimeout(() => setSaved(false), 2200); };

  if (loading) {
    return <div className="sop-app"><style>{CSS}</style>
      <div className="sop-loading sop-tracker">Loading library</div></div>;
  }

  return (
    <div className="sop-app">
      <style>{CSS}</style>

      <div className="sop-topbar">
        <div className="sop-topbar-inner">
          <div>
            <span className="sop-logo">SOP <span className="sop-logo-i">library</span></span>
            <span className="sop-logo-sub">British Columbia</span>
          </div>
          <div className="sop-tabs">
            <button className={`sop-tab ${tab === 'library' ? 'is-on' : ''}`}
              onClick={() => { setTab('library'); setOpenId(null); }}>Templates</button>
            <button className={`sop-tab ${tab === 'ref' ? 'is-on' : ''}`}
              onClick={() => { setTab('ref'); setOpenId(null); }}>BC Laws</button>
          </div>
        </div>
      </div>

      <div className="sop-hero">
        <div className="sop-hero-row">
          <div className="sop-hero-title">
            {open ? <>{open.icon} <em>{open.title}</em></>
              : tab === 'ref' ? <>BC legislation <em>reference</em></>
                : <>Template <em>library</em></>}
          </div>
          <span className="sop-tracker sop-hero-sub">
            {open ? `${catLabel(open.cat)} · BC compliance notes included`
              : tab === 'ref' ? `${BC_REFS.length} key statutes`
                : `${templates.length} templates · ${CATEGORIES.length} categories`}
          </span>
        </div>

        {tab === 'library' && !open && (
          <>
            <div className="sop-cat-grid">
              {CATEGORIES.map((c) => {
                const count = templates.filter((t) => t.cat === c.cat).length;
                return (
                  <button key={c.cat} className={`sop-cat-card ${cat === c.cat ? 'is-on' : ''}`}
                    onClick={() => setCat(cat === c.cat ? null : c.cat)}>
                    <div className="sop-cat-icon">{c.icon}</div>
                    <div>
                      <div className="sop-cat-count sop-tracker">{count} template{count === 1 ? '' : 's'}</div>
                      <div className="sop-cat-name">{c.name}</div>
                    </div>
                  </button>
                );
              })}
            </div>
            <div className="sop-cat-grid sop-btn-row">
              {CATEGORIES.map((c) => (
                <button key={c.cat} className="sop-add-btn" onClick={() => setAddingCat(c.cat)}>+ Add SOP</button>
              ))}
            </div>
          </>
        )}
      </div>

      <div className="sop-body">
        {tab === 'library' && !open && (
          <>
            <div className="sop-search-row">
              <input className="sop-input" value={query} onChange={(e) => setQuery(e.target.value)}
                placeholder="Search templates..." style={{ flex: 1, maxWidth: 380 }} />
              <div className="sop-tracker" style={{ color: '#3a6ea5' }}>{cat ? catLabel(cat) : 'All templates'}</div>
            </div>

            {(cat ? CATEGORIES.filter((c) => c.cat === cat) : CATEGORIES).map((c) => {
              const items = visible.filter((t) => t.cat === c.cat);
              return (
                <div key={c.cat}>
                  <div className="sop-sec-label">{c.icon} <span>{c.name}</span></div>
                  {items.length === 0
                    ? <div className="sop-empty">No templates in this category yet.</div>
                    : (
                      <div className="sop-tpl-grid">
                        {items.map((t) => (
                          <button key={t.id} className="sop-tpl-card" onClick={() => setOpenId(t.id)}>
                            <div className="sop-tpl-icon">{t.icon}</div>
                            <div className="sop-tpl-name">{t.title}</div>
                            <div className="sop-tpl-desc">{t.desc}</div>
                            <div>
                              <span className="sop-badge" style={catBadge(t.cat)}>{catLabel(t.cat)}</span>
                              <span className="sop-chip">BC</span>
                              {isDue(t) && <span className="sop-chip sop-chip-due">Review due</span>}
                            </div>
                          </button>
                        ))}
                      </div>
                    )}
                </div>
              );
            })}
          </>
        )}

        {tab === 'ref' && (
          <div style={{ maxWidth: 700 }}>
            <div className="sop-tracker" style={{ color: '#3a6ea5', marginBottom: 16 }}>
              British Columbia legislation quick reference
            </div>
            {BC_REFS.map((r) => (
              <div key={r.title} className="sop-ref">
                <div className="sop-ref-title">{r.title}</div>
                <div className="sop-ref-desc">{r.desc}</div>
                <div className="sop-ref-detail">{r.detail}</div>
              </div>
            ))}
            <div className="sop-disclaimer">
              This reference is for orientation only. Always verify current requirements at
              <strong> www2.gov.bc.ca</strong> or with qualified legal counsel.
            </div>
          </div>
        )}

        {open && (
          <>
            <div className="sop-detail-nav">
              <button className="sop-btn sop-btn-ghost" onClick={() => setOpenId(null)}>← Back</button>
              <span className="sop-tracker" style={{ color: '#3a6ea5' }}>{catLabel(open.cat)}</span>
            </div>

            <div className="sop-sheet">
              <div className="sop-sheet-title">{open.icon} {open.title}</div>
              <div className="sop-sheet-meta">
                Standard Operating Procedure &nbsp;·&nbsp; British Columbia, Canada &nbsp;·&nbsp; Version 1.0
              </div>

              <div className="sop-compliance">
                <strong>BC compliance notes:</strong> {open.compliance}
              </div>

              <div className="sop-sec">
                <div className="sop-sec-h">Purpose</div>
                <GrowTextarea className="sop-purpose" value={open.desc} onChange={(v) => patchOpen({ desc: v })} />
              </div>

              <div className="sop-sec">
                <div className="sop-sec-h">Details</div>
                {[
                  ['Document owner', 'owner', '[Owner name]'],
                  ['Department', 'department', ''],
                  ['Jurisdiction', 'jurisdiction', ''],
                  ['Effective date', 'effective', 'YYYY-MM-DD'],
                  ['Review date', 'review', 'YYYY-MM-DD'],
                  ['SOP reference', 'reference', '[Reference]'],
                ].map(([label, key, ph]) => (
                  <div className="sop-field-row" key={key}>
                    <span className="sop-field-label">{label}</span>
                    <input className="sop-field-val" value={open.meta[key] || ''} placeholder={ph}
                      onChange={(e) => patchOpen({ meta: { ...open.meta, [key]: e.target.value } })} />
                  </div>
                ))}
                <div className="sop-hint">
                  A review date in <code>YYYY-MM-DD</code> form that has passed flags this SOP as due
                  for review, both here and on the dashboard.
                </div>
              </div>

              <div className="sop-sec">
                <div className="sop-sec-h">Procedure steps</div>
                {open.steps.map((step, i) => (
                  <StepRow
                    key={i} n={i + 1} step={step}
                    onText={(v) => patchStep(i, v)}
                    onSubText={(si, v) => patchSub(i, si, v)}
                    onAddSub={() => addSub(i)}
                    onRemoveSub={(si) => removeSub(i, si)}
                    onRemove={() => removeStep(i)}
                  />
                ))}
                <button className="sop-btn sop-btn-ghost" style={{ marginTop: 10 }} onClick={addStep}>
                  + Add step
                </button>
              </div>

              <div className="sop-sec">
                <div className="sop-sec-h">Notes &amp; references</div>
                <GrowTextarea className="sop-notes" value={open.notes} onChange={(v) => patchOpen({ notes: v })}
                  placeholder="Add related documents, reference links, or notes..." />
              </div>

              <div style={{ display: 'flex', gap: 8, marginTop: 6, alignItems: 'center' }}>
                <button className="sop-btn sop-btn-dark" onClick={markSaved}>Save SOP</button>
                {saved && <span className="sop-saved sop-tracker">Saved</span>}
                <span className="sop-autosave">Edits save as you type</span>
              </div>

              <div className="sop-disclaimer">
                Template reflects BC legislation as of May 2026. Verify current requirements at
                www2.gov.bc.ca or with qualified legal counsel before implementation.
              </div>
            </div>
          </>
        )}
      </div>

      {addingCat && <AddSOPModal cat={addingCat} onCancel={() => setAddingCat(null)} onCreate={createSOP} />}
    </div>
  );
}

// ── STEP ROW ────────────────────────────────────────────────────────────────
function StepRow({ n, step, onText, onSubText, onAddSub, onRemoveSub, onRemove }) {
  const [openSubs, setOpenSubs] = useState(step.substeps.length > 0);
  const count = step.substeps.length;

  return (
    <div className="sop-step-group">
      <div className="sop-step-row">
        <div className="sop-step-num">{n}</div>
        <GrowTextarea className="sop-step-text" value={step.text} onChange={onText} placeholder="New step..." />
        <button className={`sop-step-toggle ${openSubs ? 'is-on' : ''}`} onClick={() => setOpenSubs(!openSubs)}>
          {openSubs ? '▼' : '►'} Sub{count > 0 ? ` (${count})` : ''}
        </button>
        <button className="sop-step-del" onClick={onRemove} title="Remove step">×</button>
      </div>

      {openSubs && (
        <div className="sop-subs">
          {step.substeps.map((s, si) => (
            <div className="sop-sub-row" key={si}>
              <div className="sop-sub-num">{n}{String.fromCharCode(97 + si)}</div>
              <GrowTextarea className="sop-sub-text" value={s} onChange={(v) => onSubText(si, v)}
                placeholder={`Sub-step ${n}${String.fromCharCode(97 + si)}...`} />
              <button className="sop-sub-del" onClick={() => onRemoveSub(si)} title="Remove">×</button>
            </div>
          ))}
          <button className="sop-add-sub" onClick={onAddSub}>+ Add sub-step</button>
        </div>
      )}
    </div>
  );
}

// ── ADD SOP MODAL ───────────────────────────────────────────────────────────
function AddSOPModal({ cat, onCancel, onCreate }) {
  const [title, setTitle] = useState('');
  const [desc, setDesc] = useState('');
  const [comp, setComp] = useState('');
  const first = useRef(null);
  useEffect(() => { first.current?.focus(); }, []);

  return (
    <div className="sop-overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) onCancel(); }}>
      <div className="sop-modal" role="dialog" aria-modal="true">
        <div className="sop-modal-head">
          <div>
            <div className="sop-tracker" style={{ color: '#3a6ea5', marginBottom: 4 }}>{catLabel(cat)}</div>
            <div className="sop-modal-title">Add new <em>SOP</em></div>
          </div>
          <button className="sop-modal-x" onClick={onCancel} aria-label="Close">×</button>
        </div>
        <div className="sop-modal-body">
          <div>
            <div className="sop-modal-lbl">SOP title</div>
            <input ref={first} className="sop-modal-input" value={title} maxLength={60}
              onChange={(e) => setTitle(e.target.value)} placeholder="e.g. Supplier onboarding" />
          </div>
          <div>
            <div className="sop-modal-lbl">Brief description</div>
            <input className="sop-modal-input" value={desc} maxLength={160}
              onChange={(e) => setDesc(e.target.value)}
              placeholder="One sentence describing the purpose of this SOP" />
          </div>
          <div>
            <div className="sop-modal-lbl">BC compliance note <span style={{ fontWeight: 400, textTransform: 'none', letterSpacing: 0, color: '#8aaad3' }}>(optional)</span></div>
            <input className="sop-modal-input" value={comp} onChange={(e) => setComp(e.target.value)}
              placeholder="Relevant BC legislation or standards that apply" />
          </div>
        </div>
        <div className="sop-modal-foot">
          <button className="sop-btn sop-btn-ghost" onClick={onCancel}>Cancel</button>
          <button className="sop-btn sop-btn-dark" disabled={!title.trim()}
            onClick={() => onCreate(title.trim(), desc.trim(), comp.trim())}>Create SOP</button>
        </div>
      </div>
    </div>
  );
}

// ── STYLES ──────────────────────────────────────────────────────────────────
// Every selector carries a sop- prefix. The original page used generic names
// (.btn, .modal-box, .topbar) which would collide with the other modules.
