// ── PROJECT TABLE ──────────────────────────────────────────────────────────
function ProjectTable({ projects, onOpenProject, onOpenModule, onNew, onImport }) {
  const [query, setQuery] = useState('');
  const [stageFilter, setStageFilter] = useState('open');

  const rows = useMemo(() => {
    const q = query.trim().toLowerCase();
    return projects
      .filter((p) => {
        if (stageFilter === 'open') return OPEN_STAGES.includes(p.stage);
        if (stageFilter !== 'all') return p.stage === stageFilter;
        return true;
      })
      .filter((p) => !q || [p.name, p.fileNo, p.client, p.gc, p.address].join(' ').toLowerCase().includes(q))
      .sort((a, b) => (b.updatedAt || '').localeCompare(a.updatedAt || ''));
  }, [projects, query, stageFilter]);

  const filters = [
    { key: 'open', label: 'Open' },
    { key: 'all', label: 'All' },
    ...STAGE_ORDER.map((s) => ({ key: s, label: STAGES[s].label })),
  ];

  return (
    <Card>
      <div className="hub-card-head">
        <div>
          <h2 className="hub-serif hub-card-title">Projects</h2>
          <div className="hub-card-note">Open a project for the full record, or go straight to a module from the rail — expenses, changes, risk, schedule.</div>
        </div>
        <div className="hub-head-tools">
          <div className="hub-search">
            <Search size={14} strokeWidth={1.8} color={C.sky} />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search projects, clients, file numbers"
              aria-label="Search projects"
            />
            {query && <button className="hub-search-clear" onClick={() => setQuery('')} aria-label="Clear search"><X size={13} strokeWidth={2} /></button>}
          </div>
          <Btn icon={FolderPlus} variant="solid" onClick={onNew}>New project</Btn>
        </div>
      </div>

      <div className="hub-filters">
        {filters.map((f) => (
          <button
            key={f.key}
            className={`hub-chip ${stageFilter === f.key ? 'is-on' : ''}`}
            onClick={() => setStageFilter(f.key)}
          >
            {f.label}
          </button>
        ))}
      </div>

      {rows.length === 0 ? (
        <div className="hub-empty">
          <Layers size={26} strokeWidth={1.3} color={C.steel} />
          <h3 className="hub-serif">{projects.length === 0 ? <>No projects <em>yet</em></> : <>Nothing <em>matches</em></>}</h3>
          <p>{projects.length === 0
            ? 'Create a project once here and every module inherits it.'
            : 'Try a different search term or stage filter.'}</p>
          {projects.length === 0 && (
            <>
              <div className="hub-empty-actions">
                <Btn icon={Plus} variant="solid" onClick={onNew}>Create the first project</Btn>
                {onImport && <Btn onClick={onImport}>Restore from a backup file</Btn>}
              </div>
              <p className="hub-empty-hint">
                Working in a Claude artifact? Each rebuilt version starts with its own storage,
                so a workspace from an earlier version is restored from an exported file rather
                than carried across.
              </p>
            </>
          )}
        </div>
      ) : (
        <div className="hub-table-scroll">
          <table className="hub-table">
            <thead>
              <tr>
                <th style={{ width: 76 }}>File</th>
                <th>Project</th>
                <th>Client</th>
                <th style={{ width: 150 }}>Stage</th>
                <th style={{ width: 128, textAlign: 'right' }}>Contract</th>
                <th style={{ width: 96, textAlign: 'right' }}>Schedule</th>
                <th style={{ width: 144 }}>Modules</th>
                <th style={{ width: 104, textAlign: 'right' }}>Updated</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((p) => {
                const v = num(p.modules?.schedule?.varianceDays);
                const tracked = !!p.modules?.schedule?.active;
                return (
                  <tr key={p.id} onClick={() => onOpenProject(p.id)} tabIndex={0}
                      onKeyDown={(e) => { if (e.key === 'Enter') onOpenProject(p.id); }}>
                    <td className="hub-tnum hub-file">{p.fileNo || '—'}</td>
                    <td>
                      <span className="hub-row-name">{p.name || 'Untitled project'}</span>
                      {p.address && <span className="hub-row-sub">{p.address}</span>}
                    </td>
                    <td className="hub-muted">{p.client || '—'}</td>
                    <td><StagePill stage={p.stage} /></td>
                    <td className="hub-tnum" style={{ textAlign: 'right' }}>{p.contractValue ? fmtK(p.contractValue) : '—'}</td>
                    <td className="hub-tnum" style={{ textAlign: 'right' }}>
                      {!tracked ? <span className="hub-muted">—</span>
                        : v === 0 ? <span style={{ color: STATUS.complete }}>On time</span>
                        : <span style={{ color: v < 0 ? STATUS.danger : STATUS.complete }}>{v > 0 ? '+' : '−'}{Math.abs(v)}d</span>}
                    </td>
                    <td><ModuleRail project={p} onOpen={(k) => onOpenModule(k, p.id)} /></td>
                    <td className="hub-muted" style={{ textAlign: 'right', fontSize: 12 }}>{relative(p.updatedAt)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </Card>
  );
}

// ── RECORD ON THE BD PIPELINE ──────────────────────────────────────────────
// Sits on the project record. Reads the board first: if the project already has
// a card it shows that reference rather than offering to create a second one;
// otherwise one click files it under Won as a pale green ER card.
function PipelineButton({ project }) {
  const [state, setState] = useState({ status: 'checking', ref: null });

  const look = useCallback(async () => {
    const leads = await store.readKey(BD_LEADS_KEY);
    if (!Array.isArray(leads)) return setState({ status: 'ready', ref: null });
    const match = leads.find((l) => l.projectId === project.id)
      || leads.find((l) => leadNameKey(l.projectName) === leadNameKey(project.name));
    setState(match
      ? { status: 'recorded', ref: match.leadNumber || '' }
      : { status: 'ready', ref: null });
  }, [project.id, project.name]);

  useEffect(() => { look(); }, [look]);

  const add = async () => {
    setState((s) => ({ ...s, status: 'adding' }));
    const leads = (await store.readKey(BD_LEADS_KEY)) || [];
    // Prefer the PM record — it carries the detail worth putting on a card.
    const pmList = (await store.readKey(PM_PROJECTS_KEY)) || [];
    const pm = pmList.find((p) => p.id === project.id) || {
      id: project.id,
      projectName: project.name,
      address: project.address,
      jobNumber: project.fileNo,
      client: project.client,
    };
    const nextRef = nextRegisterRef(leads);
    const lead = existingRelationshipLead(pm);
    lead.leadNumber = nextRef();
    await store.writeKey(BD_LEADS_KEY, [...leads, lead]);
    setState({ status: 'recorded', ref: lead.leadNumber });
  };

  if (state.status === 'checking') return null;

  if (state.status === 'recorded') {
    return (
      <div className="hub-pipeline-tag" title="Recorded on the Business Development pipeline">
        <Briefcase size={12} strokeWidth={1.8} />
        On pipeline as <strong>{state.ref || '—'}</strong>
      </div>
    );
  }

  return (
    <button className="hub-pipeline-btn" onClick={add} disabled={state.status === 'adding'}>
      <Plus size={12} strokeWidth={2} />
      {state.status === 'adding' ? 'Adding…' : 'Add to BD pipeline'}
    </button>
  );
}

// ── PROJECT TYPE AND NOTES ─────────────────────────────────────────────────
// Both read and write the Project Management record, which owns the project
// type and the note thread. Keeping them here means the type can be set and a
// note added without opening PM, and anything written appears there too.
// The starting set comes from the work Beacon does: the planned modules this
// row used to list. It is editable, so a type the practice starts taking on can
// be added without a code change.
const DEFAULT_PROJECT_TYPES = ['Depreciation Report', 'Loan Monitoring', 'Estimating', 'Report Library'];
const PROJECT_TYPES_KEY = 'beacon-project-types';

// Reads the PM record for a project and gives back a setter that writes to it.
function usePmRecord(projectId) {
  const [record, setRecord] = useState(null);

  const load = useCallback(async () => {
    const list = (await store.readKey(PM_PROJECTS_KEY)) || [];
    setRecord(list.find((p) => p.id === projectId) || null);
  }, [projectId]);

  useEffect(() => { load(); }, [load]);

  const patch = useCallback(async (changes) => {
    const list = (await store.readKey(PM_PROJECTS_KEY)) || [];
    const next = list.map((p) => (p.id === projectId ? { ...p, ...changes } : p));
    await store.writeKey(PM_PROJECTS_KEY, next);
    setRecord(next.find((p) => p.id === projectId) || null);
  }, [projectId]);

  return [record, patch];
}

function ProjectTypePicker({ record, onPatch }) {
  const [types, setTypes] = useState(DEFAULT_PROJECT_TYPES);
  const [adding, setAdding] = useState(false);
  const [draft, setDraft] = useState('');
  const inputRef = useRef(null);
  const current = record?.projectType || '';

  useEffect(() => {
    let live = true;
    store.readKey(PROJECT_TYPES_KEY).then((stored) => {
      if (live && Array.isArray(stored) && stored.length) setTypes(stored);
    });
    return () => { live = false; };
  }, []);

  useEffect(() => { if (adding) inputRef.current?.focus(); }, [adding]);

  const addType = async () => {
    const name = draft.trim();
    if (!name) { setAdding(false); setDraft(''); return; }
    // Case-insensitive match, so the same type isn't added twice in different
    // capitalisation. An existing one is simply selected.
    const found = types.find((t) => t.toLowerCase() === name.toLowerCase());
    if (!found) {
      const next = [...types, name];
      setTypes(next);
      await store.writeKey(PROJECT_TYPES_KEY, next);
    }
    onPatch({ projectType: found || name });
    setAdding(false);
    setDraft('');
  };

  return (
    <div className="hub-type-row">
      {/* Left of the line, so the types keep their reading order. */}
      {adding ? (
        <input
          ref={inputRef}
          className="hub-type-input"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={addType}
          onKeyDown={(e) => {
            if (e.key === 'Enter') addType();
            if (e.key === 'Escape') { setAdding(false); setDraft(''); }
          }}
          placeholder="Type name"
        />
      ) : (
        <button className="hub-type-add" onClick={() => setAdding(true)} title="Add a project type">
          <Plus size={11} strokeWidth={2} /> Add type
        </button>
      )}

      {types.map((t) => {
        const on = current === t;
        return (
          <button
            key={t}
            className={`hub-type ${on ? 'is-on' : ''}`}
            aria-pressed={on}
            // Clicking the selected one clears it, so a type set by mistake
            // doesn't have to stay.
            onClick={() => onPatch({ projectType: on ? '' : t })}
          >
            {t}
          </button>
        );
      })}
    </div>
  );
}

function ProjectNotes({ record, onPatch }) {
  const [draft, setDraft] = useState('');
  const notes = Array.isArray(record?.notes) ? record.notes : [];

  // Date and time, matching the note threads in the modules.
  const stamp = (ts) => {
    if (!ts) return '';
    const d = new Date(ts);
    return d.toLocaleDateString('en-CA', { year: 'numeric', month: 'short', day: 'numeric' })
      + ' at ' + d.toLocaleTimeString('en-CA', { hour: '2-digit', minute: '2-digit', hour12: false });
  };

  const add = () => {
    const text = draft.trim();
    if (!text) return;
    onPatch({ notes: [...notes, { id: uid(), text, ts: Date.now() }] });
    setDraft('');
  };

  return (
    <Card className="hub-card-pad">
      <Label style={{ marginBottom: 12 }}>Notes</Label>
      {notes.length === 0 ? (
        <p className="hub-notes-empty">No notes yet. Anything added here appears on the project in Project Management.</p>
      ) : (
        <ul className="hub-notes">
          {[...notes].sort((a, b) => (b.ts || 0) - (a.ts || 0)).map((n) => (
            <li key={n.id}>
              <div className="hub-note-meta">
                {stamp(n.ts)}{n.edited ? ` · edited ${stamp(n.edited)}` : ''}
              </div>
              <div className="hub-note-text">{n.text}</div>
            </li>
          ))}
        </ul>
      )}
      <textarea
        className="hub-note-input"
        rows={2}
        value={draft}
        onChange={(e) => setDraft(e.target.value)}
        placeholder="Site visits, calls, decisions — anything worth a record"
      />
      <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: 8 }}>
        <Btn icon={Plus} variant="solid" onClick={add} disabled={!draft.trim()}>Add note</Btn>
      </div>
    </Card>
  );
}

// ── PROJECT DETAIL ─────────────────────────────────────────────────────────
function ProjectDetail({ project, onBack, onEdit, onDelete, onOpenModule }) {
  const [pmRecord, patchPm] = usePmRecord(project.id);
  const meta = [
    { label: 'Client', value: project.client, icon: Building2 },
    { label: 'General contractor', value: project.gc, icon: HardHat },
    { label: 'Address', value: project.address, icon: MapPin },
    { label: 'Schedule', value: project.start || project.finish ? `${fmtDate(project.start)} → ${fmtDate(project.finish)}` : '', icon: Clock },
  ];

  const figures = [
    { label: 'Contract value', value: project.contractValue ? fmt(project.contractValue) : '—' },
    { label: 'Estimated value', value: project.estimate ? fmt(project.estimate) : '—' },
    { label: 'Approved changes', value: fmt(project.modules?.change?.agreedValue) },
    {
      label: 'Contingency held',
      value: project.modules?.risk?.active
        ? `${fmt(project.modules.risk.allowance)}${project.estimate ? `  ·  ${((num(project.modules.risk.allowance) / num(project.estimate)) * 100).toFixed(1)}%` : ''}`
        : '—',
    },
  ];

  return (
    <>
      <div className="hub-detail-nav">
        <Btn icon={ArrowLeft} onClick={onBack}>All projects</Btn>
        <div style={{ flex: 1 }} />
        <Btn icon={Pencil} onClick={onEdit}>Edit details</Btn>
        <Btn icon={Trash2} variant="danger" onClick={onDelete}>Delete project</Btn>
      </div>

      <Card className="hub-card-pad" style={{ marginBottom: 20 }}>
        <div className="hub-detail-head">
          <div>
            <Label style={{ marginBottom: 8 }}>File {project.fileNo || '—'}</Label>
            <h1 className="hub-serif hub-detail-title">{project.name || 'Untitled project'}</h1>
          </div>
          <div className="hub-detail-actions">
            <StagePill stage={project.stage} />
            <PipelineButton project={project} />
          </div>
        </div>

        <div className="hub-meta-grid">
          {meta.filter((m) => m.value).map((m) => (
            <div key={m.label} className="hub-meta">
              <m.icon size={14} strokeWidth={1.6} color={C.sky} />
              <div>
                <Label style={{ marginBottom: 3 }}>{m.label}</Label>
                <div className="hub-meta-value">{m.value}</div>
              </div>
            </div>
          ))}
        </div>

        <div className="hub-figures">
          {figures.map((f) => (
            <div key={f.label}>
              <Label style={{ marginBottom: 6 }}>{f.label}</Label>
              <div className="hub-serif hub-tnum hub-figure">{f.value}</div>
            </div>
          ))}
        </div>
      </Card>

      <Label style={{ margin: '0 0 12px 2px' }}>Modules</Label>
      <div className="hub-mod-cards">
        {LIVE_PROJECT_MODULES.map((m) => {
          const data = project.modules?.[m.key];
          const on = !!data?.active;
          return (
            <Card key={m.key} className="hub-card-pad hub-mod-card">
              <div className="hub-mod-card-top">
                <span className="hub-mod-icon"><m.icon size={17} strokeWidth={1.5} /></span>
                <span className={`hub-state ${on ? 'is-on' : ''}`}>{on ? 'In use' : 'Not started'}</span>
              </div>
              <div className="hub-serif hub-mod-card-name">{m.name}</div>
              <div className="hub-mod-card-stat hub-tnum">{on ? m.stat(data) : 'No data recorded for this project'}</div>
              <Btn variant={on ? 'ghost' : 'solid'} onClick={() => onOpenModule(m.key, project.id)} style={{ marginTop: 14 }}>
                {on ? 'Open' : 'Start'} {m.name.toLowerCase()}
              </Btn>
            </Card>
          );
        })}
      </div>

      <div style={{ marginTop: 26 }}>
        <ProjectNotes record={pmRecord} onPatch={patchPm} />
      </div>

      <Label style={{ margin: '30px 0 12px 2px' }}>Project type</Label>
      <ProjectTypePicker record={pmRecord} onPatch={patchPm} />
    </>
  );
}

// ── UNATTACHED MODULE PLACEHOLDER ──────────────────────────────────────────
// Shown when a module key has no component registered yet.
function ModuleMount({ module: m, project }) {
  const isFirm = m.scope === 'firm';
  const component = m.name.replace(/[^A-Za-z]/g, '');

  return (
    <Card className="hub-card-pad" style={{ textAlign: 'center', padding: '64px 40px' }}>
      <span className="hub-mod-icon" style={{ margin: '0 auto' }}><m.icon size={22} strokeWidth={1.4} /></span>
      <h2 className="hub-serif" style={{ fontSize: 26, color: C.navy, fontWeight: 600, margin: '18px 0 8px' }}>
        {m.name} <em style={{ color: C.steel }}>not attached yet</em>
      </h2>
      <p style={{ fontSize: 14, color: C.steel, maxWidth: 470, margin: '0 auto 28px', lineHeight: 1.6 }}>
        {isFirm
          ? <>This module runs across the whole practice rather than one job, so it reads the firm record and never attaches to a project.</>
          : project
            ? <>The button is wired. Register the component against <code className="hub-inline">{m.key}</code> and it opens against <strong style={{ color: C.navy }}>{project.name}</strong> — file {project.fileNo || '—'}.</>
            : <>Pick a project first, or the module opens with its own project picker.</>}
      </p>

      <div className="hub-contract">
        <Label style={{ marginBottom: 10 }}>Register it here</Label>
        <code>{`const MODULE_COMPONENTS = {
  ${m.key}: ${component},
};`}</code>
      </div>
      <p style={{ fontSize: 12, color: C.sky, marginTop: 14 }}>
        Requires a multi-file project — the artifact sandbox resolves no local modules.
      </p>
    </Card>
  );
}

// ── ERROR BOUNDARY ─────────────────────────────────────────────────────────
// A module blowing up shouldn't take the hub down with it — the project list
// and every other module stay reachable.
class ModuleErrorBoundary extends React.Component {
  constructor(props) { super(props); this.state = { error: null }; }
  static getDerivedStateFromError(error) { return { error }; }
  componentDidUpdate(prev) {
    if (prev.resetKey !== this.props.resetKey && this.state.error) this.setState({ error: null });
  }
  render() {
    if (this.state.error) return this.props.fallback(this.state.error);
    return this.props.children;
  }
}

function ModuleCrash({ module: m, error, onBack }) {
  return (
    <Card className="hub-card-pad" style={{ textAlign: 'center', padding: '56px 40px' }}>
      <AlertTriangle size={26} strokeWidth={1.4} color={STATUS.danger} />
      <h2 className="hub-serif" style={{ fontSize: 24, color: C.navy, fontWeight: 600, margin: '14px 0 8px' }}>
        {m.name} stopped <em style={{ color: C.steel }}>responding</em>
      </h2>
      <p style={{ fontSize: 13.5, color: C.steel, maxWidth: 440, margin: '0 auto 20px', lineHeight: 1.6 }}>
        The rest of the workspace is unaffected. The error was:
      </p>
      <div className="hub-contract" style={{ maxWidth: 520 }}>
        <code style={{ color: STATUS.danger }}>{String(error?.message || error)}</code>
      </div>
      <Btn icon={ArrowLeft} onClick={onBack} style={{ marginTop: 22 }}>Back to project</Btn>
    </Card>
  );
}

// ── MODULE HOST ────────────────────────────────────────────────────────────
// Wraps whichever module is open in a persistent bar carrying the project
// identity and a rail to hop between modules without going back first.
function ModuleHost({ module: m, project, firm, ensureLeads, onLeadWon, onBack, onHome, onSwitch, onSummary }) {
  const Component = MODULE_COMPONENTS[m.key];
  const isFirm = m.scope === 'firm';
  const scoped = !isFirm && project;

  return (
    <>
      <div className="hub-modbar">
        <Btn icon={ArrowLeft} variant="solid" onClick={onHome}>Back to dashboard</Btn>
        {scoped && (
          <Btn onClick={onBack}>{project.name || 'Project'}</Btn>
        )}
        <div className="hub-modbar-title">
          <span className="hub-serif">{m.name}</span>
          {scoped && <span className="hub-modbar-sub">{project.name} · file {project.fileNo || '—'}</span>}
          {isFirm && <span className="hub-modbar-sub">Practice-wide</span>}
        </div>
        {scoped && (
          <div className="hub-rail hub-modbar-rail">
            {LIVE_PROJECT_MODULES.map((o) => (
              <button
                key={o.key}
                className={`hub-rail-cell ${o.key === m.key ? 'is-on' : ''}`}
                title={o.name}
                aria-label={`Switch to ${o.name}`}
                aria-current={o.key === m.key ? 'true' : undefined}
                onClick={() => onSwitch(o.key)}
              >
                <o.icon size={13} strokeWidth={1.9} />
              </button>
            ))}
          </div>
        )}
      </div>

      {Component ? (
        <ModuleErrorBoundary
          resetKey={`${m.key}:${project?.id || 'firm'}`}
          fallback={(err) => <ModuleCrash module={m} error={err} onBack={onBack} />}
        >
          <Component
            {...(isFirm ? { firm: firm?.[m.key] } : { project })}
            {...(m.key === 'bizdev' ? { ensureLeads, onLeadWon } : {})}
            onSummary={onSummary}
            onExit={onBack}
          />
        </ModuleErrorBoundary>
      ) : (
        <ModuleMount module={m} project={project} />
      )}
    </>
  );
}

// ── PROJECT MODAL ──────────────────────────────────────────────────────────
function ProjectModal({ initial, prefill, onSave, onCancel }) {
  // `prefill` seeds a new record — from a won lead — without turning the form
  // into an edit of an existing one.
  const seed = initial || prefill;
  const isNew = !initial;
  const [f, setF] = useState(() => ({
    fileNo: seed?.fileNo || '', name: seed?.name || '', client: seed?.client || '',
    address: seed?.address || '', gc: seed?.gc || '', stage: seed?.stage || 'precon',
    contractValue: seed?.contractValue || '', estimate: seed?.estimate || '',
    start: seed?.start || '', finish: seed?.finish || '',
  }));
  const firstRef = useRef(null);
  useEffect(() => { firstRef.current?.focus(); }, []);

  const set = (k) => (e) => setF((s) => ({ ...s, [k]: e.target.value }));
  const valid = f.name.trim().length > 0;

  const submit = () => {
    if (!valid) return;
    onSave({
      ...f,
      name: f.name.trim(),
      fileNo: f.fileNo.trim(),
      contractValue: num(f.contractValue),
      estimate: num(f.estimate),
    });
  };

  return (
    <div className="hub-overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) onCancel(); }}>
      <div className="hub-modal" role="dialog" aria-modal="true" aria-label={isNew ? 'New project' : 'Edit project'}>
        <div className="hub-modal-head">
          <h2 className="hub-serif">{isNew ? <>New <em>project</em></> : <>Edit <em>details</em></>}</h2>
          <button className="hub-icon-btn" onClick={onCancel} aria-label="Close"><X size={16} strokeWidth={1.8} /></button>
        </div>

        <div className="hub-modal-body">
          <div className="hub-form">
            <Field label="File number"><input ref={firstRef} className="hub-input hub-tnum" value={f.fileNo} onChange={set('fileNo')} placeholder="25076" /></Field>
            <Field label="Stage">
              <select className="hub-input" value={f.stage} onChange={set('stage')}>
                {STAGE_ORDER.map((s) => <option key={s} value={s}>{STAGES[s].label}</option>)}
              </select>
            </Field>
            <Field label="Project name" span={2}><input className="hub-input" value={f.name} onChange={set('name')} placeholder="1800 McKenzie" /></Field>
            <Field label="Client" span={2}><input className="hub-input" value={f.client} onChange={set('client')} placeholder="McKenzie Holdings Ltd." /></Field>
            <Field label="Address" span={2}><input className="hub-input" value={f.address} onChange={set('address')} placeholder="1800 McKenzie Ave, Victoria BC" /></Field>
            <Field label="General contractor" span={2}><input className="hub-input" value={f.gc} onChange={set('gc')} placeholder="To be appointed" /></Field>
            <Field label="Contract value"><input className="hub-input hub-tnum" type="number" value={f.contractValue} onChange={set('contractValue')} placeholder="0.00" /></Field>
            <Field label="Estimated value"><input className="hub-input hub-tnum" type="number" value={f.estimate} onChange={set('estimate')} placeholder="0.00" /></Field>
            <Field label="Start"><input className="hub-input hub-tnum" type="date" value={f.start} onChange={set('start')} /></Field>
            <Field label="Finish"><input className="hub-input hub-tnum" type="date" value={f.finish} onChange={set('finish')} /></Field>
          </div>
        </div>

        <div className="hub-modal-foot">
          <Btn onClick={onCancel}>Cancel</Btn>
          <Btn icon={Check} variant="solid" onClick={submit} disabled={!valid}>
            {isNew ? 'Create project' : 'Save changes'}
          </Btn>
        </div>
      </div>
    </div>
  );
}

// In-app confirm — the sandbox iframe suppresses window.confirm.
function ConfirmDelete({ project, onConfirm, onCancel }) {
  return (
    <div className="hub-overlay" onMouseDown={(e) => { if (e.target === e.currentTarget) onCancel(); }}>
      <div className="hub-modal" style={{ maxWidth: 440 }} role="dialog" aria-modal="true">
        <div className="hub-modal-head">
          <h2 className="hub-serif">Delete <em>project</em></h2>
          <button className="hub-icon-btn" onClick={onCancel} aria-label="Close"><X size={16} strokeWidth={1.8} /></button>
        </div>
        <div className="hub-modal-body">
          <div className="hub-warn">
            <AlertTriangle size={16} strokeWidth={1.7} color={STATUS.danger} />
            <div>
              <strong>{project.name || 'Untitled project'}</strong> and every module record attached to it will be removed. This cannot be undone.
            </div>
          </div>
        </div>
        <div className="hub-modal-foot">
          <Btn onClick={onCancel}>Keep project</Btn>
          <Btn icon={Trash2} variant="danger-solid" onClick={onConfirm}>Delete permanently</Btn>
        </div>
      </div>
    </div>
  );
}

// ── BACKUP AND RESTORE ─────────────────────────────────────────────────────
// Everything lives in browser or sandbox storage, which is per-machine and
// does not survive a rebuilt artifact. Exporting writes every module's records
// to one file so a test workspace can be carried across versions.
const BACKUP_VERSION = 1;

async function exportWorkspace() {
  const keys = await store.listKeys([...PROJECT_PREFIXES, ...BD_PREFIXES]);
  const data = {};
  for (const key of keys) {
    const value = await store.readKey(key);
    if (value !== null) data[key] = value;
  }
  const payload = {
    beaconWorkspace: BACKUP_VERSION,
    exportedAt: new Date().toISOString(),
    keys: Object.keys(data).length,
    data,
  };
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `beacon-workspace-${new Date().toISOString().slice(0, 10)}.json`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  return Object.keys(data).length;
}

async function importWorkspace(text) {
  const parsed = JSON.parse(text);
  if (!parsed || !parsed.data || typeof parsed.data !== 'object') {
    throw new Error('Not a Beacon workspace file.');
  }
  // Replace rather than merge — a half-merged workspace is worse than either.
  const existing = await store.listKeys([...PROJECT_PREFIXES, ...BD_PREFIXES]);
  for (const key of existing) await store.remove(key);
  const entries = Object.entries(parsed.data);
  for (const [key, value] of entries) await store.writeKey(key, value);
  return entries.length;
}

// ── RESET WORKSPACE ────────────────────────────────────────────────────────
// Clearing the code's sample data isn't enough on its own: records written to
// storage during testing survive, because modules only seed when storage is
// empty. This clears them for real.
function ResetModal({ onConfirm, onCancel }) {
  const [includeBD, setIncludeBD] = useState(false);
  const [busy, setBusy] = useState(false);

  return (
    <div className="hub-overlay" onMouseDown={(e) => { if (e.target === e.currentTarget && !busy) onCancel(); }}>
      <div className="hub-modal" style={{ maxWidth: 520 }} role="dialog" aria-modal="true">
        <div className="hub-modal-head">
          <h2 className="hub-serif">Reset <em>workspace</em></h2>
          <button className="hub-icon-btn" onClick={onCancel} disabled={busy} aria-label="Close">
            <X size={16} strokeWidth={1.8} />
          </button>
        </div>

        <div className="hub-modal-body">
          <div className="hub-warn" style={{ marginBottom: 16 }}>
            <AlertTriangle size={16} strokeWidth={1.7} color={STATUS.danger} />
            <div>Every project and all module records will be permanently removed. This cannot be undone.</div>
          </div>

          <Label style={{ marginBottom: 8 }}>This will clear</Label>
          <ul className="hub-reset-list">
            <li>All projects on the dashboard</li>
            <li>Expense Tracker ledgers, Risk Registers and Schedules</li>
            <li>The Project Management register, lenders and developers</li>
            <li>The Cost Analysis library</li>
            <li>The SOP Library, back to the 17 bundled templates</li>
          </ul>

          <label className="hub-reset-opt">
            <input type="checkbox" checked={includeBD} onChange={(e) => setIncludeBD(e.target.checked)} />
            <span>
              <strong>Also clear Business Development</strong>
              <em>Leads, the developer watchlist and any uploaded plan files. Left alone by default.</em>
            </span>
          </label>
        </div>

        <div className="hub-modal-foot">
          <Btn onClick={onCancel} disabled={busy}>Cancel</Btn>
          <Btn icon={Trash2} variant="danger-solid" disabled={busy}
            onClick={async () => { setBusy(true); await onConfirm(includeBD); }}>
            {busy ? 'Clearing…' : 'Reset workspace'}
          </Btn>
        </div>
      </div>
    </div>
  );
}

// ── ROOT ───────────────────────────────────────────────────────────────────
export default function BeaconHub() {
  const [state, setState] = useState({ projects: [] });
  const [ready, setReady] = useState(false);
  const [view, setView] = useState({ kind: 'hub' });
  const [editing, setEditing] = useState(null);   // { project } | { isNew: true }
  const [deleting, setDeleting] = useState(null);
  const [resetting, setResetting] = useState(false);
  const [ensureLeads, setEnsureLeads] = useState([]);
  const [notice, setNotice] = useState(null);
  const fileRef = useRef(null);
  // Set while a won lead is waiting on the project form.
  const pendingWin = useRef(null);

  useEffect(() => {
    let cancelled = false;
    store.load().then(async (loaded) => {
      if (cancelled) return;
      const base = loaded && Array.isArray(loaded.projects) ? loaded : seedState();
      // Older saves predate the firm record — backfill rather than discard.
      const merged = await syncProjectRegister(base.projects);
      if (cancelled) return;
      setState({ ...base, projects: merged, firm: { ...blankFirm(), ...(base.firm || {}) } });
      setReady(true);
    });
    return () => { cancelled = true; };
  }, []);

  useEffect(() => { if (ready) store.save(state); }, [state, ready]);

  // Mirror hub project edits into Project Management. Runs on every change to
  // the project list so the two registers can't drift while you work.
  useEffect(() => {
    if (!ready) return;
    syncProjectRegister(state.projects);
  }, [ready, state.projects]);

  const projects = state.projects;
  const firm = state.firm || blankFirm();
  const activeProject = view.projectId ? projects.find((p) => p.id === view.projectId) : null;

  const upsertProject = useCallback((meta, id) => {
    setState((s) => {
      if (id) {
        return { ...s, projects: s.projects.map((p) => (p.id === id ? { ...p, ...meta, updatedAt: nowISO() } : p)) };
      }
      return { ...s, projects: [newProject(meta), ...s.projects] };
    });
  }, []);

  const removeProject = useCallback((id) => {
    setState((s) => ({ ...s, projects: s.projects.filter((p) => p.id !== id) }));
  }, []);

  // Modules call this to push their figures back into the shared record.
  const updateModuleSummary = useCallback((projectId, moduleKey, summary) => {
    setState((s) => ({
      ...s,
      projects: s.projects.map((p) => p.id !== projectId ? p : {
        ...p,
        updatedAt: nowISO(),
        modules: { ...p.modules, [moduleKey]: { ...p.modules[moduleKey], active: true, ...summary } },
      }),
    }));
  }, []);

  // Firm-scope modules (SOP, Business Development) write here instead.
  const updateFirmSummary = useCallback((moduleKey, summary) => {
    setState((s) => ({
      ...s,
      firm: { ...(s.firm || blankFirm()), [moduleKey]: { ...(s.firm?.[moduleKey] || {}), active: true, ...summary } },
    }));
  }, []);

  // A lead reaching Won becomes a project. Called by Business Development,
  // which stores the returned id on the card so the two stay linked and a
  // second project is never created if the card moves out of Won and back.
  //
  // The project starts in pre-construction: winning the work is not the same
  // as being on site, and the stage is the first thing to correct once it is.
  const promoteLeadToProject = useCallback((lead) => new Promise((resolve) => {
    const existing = state.projects.find((p) => p.leadId === lead.id);
    if (existing) { resolve(existing.id); return; }

    // Open the ordinary New project form with the lead's details filled in, so
    // the record is reviewed and completed rather than appearing unseen. The
    // job number is left blank: that is assigned by the practice, not
    // inherited from a BD reference. Pre-construction, because winning work is
    // not the same as being on site.
    pendingWin.current = { lead, resolve };
    setEditing({
      isNew: true,
      prefill: {
        fileNo: '',
        name: lead.projectName || '',
        client: lead.owner?.name || lead.developer || '',
        address: lead.address || '',
        gc: '',
        stage: 'precon',
        contractValue: '',
        estimate: num(lead.estValue) || '',
        start: '',
        finish: '',
      },
    });
  }), [state.projects]);

  // Clears every module's records, not just the hub's. Modules re-seed their
  // own scaffolding (Risk categories, SOP templates) on next open.
  const resetWorkspace = useCallback(async (includeBD) => {
    const prefixes = includeBD ? [...PROJECT_PREFIXES, ...BD_PREFIXES] : PROJECT_PREFIXES;
    const keys = await store.listKeys(prefixes);
    for (const key of keys) await store.remove(key);
    if (includeBD) {
      try { indexedDB.deleteDatabase('beacon-bd'); } catch (err) { /* no plan files stored */ }
    }
    setState({ projects: [], firm: blankFirm() });
    setView({ kind: 'hub' });
    setResetting(false);
  }, []);

  const doExport = useCallback(async () => {
    try {
      const n = await exportWorkspace();
      setNotice({ kind: 'ok', text: `Exported ${n} record set${n === 1 ? '' : 's'}.` });
    } catch (err) {
      setNotice({ kind: 'bad', text: 'Export failed: ' + err.message });
    }
  }, []);

  const doImport = useCallback(async (file) => {
    try {
      const n = await importWorkspace(await file.text());
      const loaded = await store.load();
      const base = loaded && Array.isArray(loaded.projects) ? loaded : seedState();
      const merged = await syncProjectRegister(base.projects);
      setState({ ...base, projects: merged, firm: { ...blankFirm(), ...(base.firm || {}) } });
      setView({ kind: 'hub' });
      setNotice({ kind: 'ok', text: `Restored ${n} record set${n === 1 ? '' : 's'}.` });
    } catch (err) {
      setNotice({ kind: 'bad', text: 'Import failed: ' + err.message });
    }
  }, []);

  // Reconcile before a module mounts, so it opens against current data rather
  // than whatever was in storage when the dashboard last synced. Business
  // Development in particular needs the Existing Relationships backfill to have
  // run before its board renders.
  const openModule = (moduleKey, projectId) => {
    const target = { kind: 'module', moduleKey, projectId: projectId ?? view.projectId };
    if (!ready) { setView(target); return; }
    syncProjectRegister(state.projects)
      .then(async (merged) => {
        if (merged.length !== state.projects.length) {
          setState((s) => ({ ...s, projects: merged }));
        }
        // BD merges these itself, which works even on a first visit.
        setEnsureLeads(moduleKey === 'bizdev' ? await existingRelationshipLeads() : []);
        setView(target);
      })
      .catch(() => setView(target));
  };
  const openProject = (id) => setView({ kind: 'project', projectId: id });
  // Returning from a module is the moment to pick up anything created inside
  // Project Management, since only one module is mounted at a time.
  const backToHub = () => {
    setView({ kind: 'hub' });
    if (ready) {
      syncProjectRegister(state.projects).then((merged) => {
        if (merged.length !== state.projects.length) {
          setState((s) => ({ ...s, projects: merged }));
        }
      });
    }
  };

  const styles = <style>{CSS}</style>;

  if (!ready) {
    return <div className="beacon-hub">{styles}<div className="hub-loading hub-tracker">Loading workspace</div></div>;
  }

  const moduleDef = view.kind === 'module' ? MODULES.find((m) => m.key === view.moduleKey) : null;

  return (
    <div className="beacon-hub">
      {styles}

      {view.kind !== 'module' && (
      <header className="hub-topbar">
        <div className="hub-topbar-inner">
          <button className="hub-brand" onClick={backToHub}>
            <span className="hub-brand-mark"><LayoutGrid size={16} strokeWidth={1.7} /></span>
            <span>
              <span className="hub-serif hub-brand-name">Beacon</span>
              <span className="hub-tracker hub-brand-sub">Project control centre</span>
            </span>
          </button>

          <nav className="hub-crumbs hub-tracker">
            <button onClick={backToHub} className={view.kind === 'hub' ? 'is-here' : ''}>Dashboard</button>
            {activeProject && (
              <>
                <ChevronRight size={12} strokeWidth={2} />
                <button onClick={() => openProject(activeProject.id)} className={view.kind === 'project' ? 'is-here' : ''}>
                  {activeProject.name || 'Untitled'}
                </button>
              </>
            )}
            {moduleDef && (<><ChevronRight size={12} strokeWidth={2} /><span className="is-here">{moduleDef.name}</span></>)}
          </nav>

          <Btn icon={Plus} variant="solid" onClick={() => setEditing({ isNew: true })}>New project</Btn>
        </div>
      </header>
      )}

      <main className={`hub-main ${view.kind === 'module' ? 'hub-main-module' : ''}`}>
        {view.kind === 'hub' && (
          <>
            <div className="hub-hero">
              <h1 className="hub-serif hub-hero-title">
                {greeting()}, here's the <em>portfolio</em>.
              </h1>
              <p className="hub-hero-sub">
                {projects.filter((p) => OPEN_STAGES.includes(p.stage)).length} active job
                {projects.filter((p) => OPEN_STAGES.includes(p.stage)).length === 1 ? '' : 's'} · {fmtDate(todayISO())}
              </p>
            </div>

            <KpiStrip projects={projects} />

            <div style={{ marginTop: 32 }}>
              <ProjectTable
                projects={projects}
                onOpenProject={openProject}
                onOpenModule={openModule}
                onNew={() => setEditing({ isNew: true })}
                onImport={() => fileRef.current?.click()}
              />
            </div>

            <Label style={{ margin: '36px 0 12px 2px' }}>Practice</Label>
            <PracticeGrid firm={firm} onOpen={(k) => openModule(k, null)} />
          </>
        )}

        {view.kind === 'project' && activeProject && (
          <ProjectDetail
            project={activeProject}
            onBack={backToHub}
            onEdit={() => setEditing({ project: activeProject })}
            onDelete={() => setDeleting(activeProject)}
            onOpenModule={openModule}
          />
        )}

        {view.kind === 'project' && !activeProject && (
          <Card className="hub-card-pad hub-empty"><h3 className="hub-serif">Project not <em>found</em></h3><p>It may have been deleted.</p><Btn icon={ArrowLeft} onClick={backToHub}>Back to dashboard</Btn></Card>
        )}

        {view.kind === 'module' && moduleDef && (
          <ModuleHost
            module={moduleDef}
            project={activeProject}
            firm={firm}
            onSwitch={(k) => openModule(k, activeProject?.id)}
            onHome={backToHub}
            onBack={() => (activeProject && moduleDef.scope !== 'firm' ? openProject(activeProject.id) : backToHub())}
            ensureLeads={ensureLeads}
            onLeadWon={promoteLeadToProject}
            onSummary={(summary) => {
              if (moduleDef.scope === 'firm') updateFirmSummary(moduleDef.key, summary);
              else if (activeProject) updateModuleSummary(activeProject.id, moduleDef.key, summary);
            }}
          />
        )}

        <footer className="hub-footer">
          <span className="hub-tracker">{projects.length} project{projects.length === 1 ? '' : 's'} · {LIVE_PROJECT_MODULES.length} project modules · {FIRM_MODULES.length} practice modules · stored locally</span>
          <span style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
            <button className="hub-reset-link hub-safe-link" onClick={doExport}>Export</button>
            <button className="hub-reset-link hub-safe-link" onClick={() => fileRef.current?.click()}>Import</button>
            <input ref={fileRef} type="file" accept="application/json,.json" style={{ display: 'none' }}
              onChange={(e) => { const f = e.target.files?.[0]; if (f) doImport(f); e.target.value = ''; }} />
            <button className="hub-reset-link" onClick={() => setResetting(true)}>Reset workspace</button>
            <span className="hub-serif" style={{ fontStyle: 'italic', fontSize: 14 }}>beacon</span>
          </span>
        </footer>
      </main>

      {editing && (
        <ProjectModal
          initial={editing.project}
          prefill={editing.prefill}
          onSave={(meta) => {
            const win = pendingWin.current;
            if (win) {
              // Created from a won lead: build it here so the id can be handed
              // back to Business Development for the link.
              const project = newProject({ ...meta, leadId: win.lead.id, leadRef: win.lead.leadNumber || '' });
              setState((s) => ({ ...s, projects: [project, ...s.projects] }));
              syncProjectRegister([project, ...state.projects]);
              pendingWin.current = null;
              win.resolve(project.id);
            } else {
              upsertProject(meta, editing.project?.id);
            }
            setEditing(null);
          }}
          onCancel={() => {
            if (pendingWin.current) { pendingWin.current.resolve(null); pendingWin.current = null; }
            setEditing(null);
          }}
        />
      )}
      {notice && (
        <div className={`hub-notice hub-notice-${notice.kind}`} role="status">
          {notice.text}
          <button className="hub-icon-btn" onClick={() => setNotice(null)} aria-label="Dismiss">
            <X size={14} strokeWidth={1.8} />
          </button>
        </div>
      )}
      {resetting && (
        <ResetModal onCancel={() => setResetting(false)} onConfirm={resetWorkspace} />
      )}
      {deleting && (
        <ConfirmDelete
          project={deleting}
          onConfirm={() => { removeProject(deleting.id); setDeleting(null); backToHub(); }}
          onCancel={() => setDeleting(null)}
        />
      )}
    </div>
  );
}

function greeting() {
  const h = new Date().getHours();
  if (h < 12) return 'Good morning';
  if (h < 17) return 'Good afternoon';
  return 'Good evening';
}

// ── STYLES ─────────────────────────────────────────────────────────────────
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,400;9..144,500;9..144,600;9..144,700&family=Manrope:wght@400;500;600;700&display=swap');

.beacon-hub { font-family: 'Manrope', system-ui, sans-serif; background: ${C.paper}; color: ${C.ink};
  min-height: 100vh; -webkit-font-smoothing: antialiased; }
.beacon-hub *, .beacon-hub *::before, .beacon-hub *::after { box-sizing: border-box; }
.beacon-hub .hub-serif { font-family: 'Fraunces', Georgia, serif; }
.beacon-hub .hub-tnum { font-variant-numeric: tabular-nums; }
.beacon-hub .hub-tracker { font-size: 10px; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; }
.beacon-hub button { font-family: inherit; }
.beacon-hub :focus-visible { outline: 2px solid ${C.steel}; outline-offset: 2px; }

.hub-loading { padding: 80px; text-align: center; color: ${C.steel}; }

/* Top bar */
.hub-topbar { background: ${C.white}; border-bottom: 1px solid ${C.ice}; position: sticky; top: 0; z-index: 40; }
.hub-topbar-inner { max-width: 1320px; margin: 0 auto; padding: 14px 32px; display: flex; align-items: center; gap: 24px; }
.hub-brand { display: flex; align-items: center; gap: 11px; background: none; border: none; padding: 0; cursor: pointer; text-align: left; }
.hub-brand-mark { width: 32px; height: 32px; display: grid; place-items: center; background: ${C.navy}; color: ${C.white}; border-radius: 3px; }
.hub-brand-name { display: block; font-size: 17px; font-weight: 600; color: ${C.navy}; line-height: 1.1; }
.hub-brand-sub { display: block; color: ${C.sky}; margin-top: 2px; }
.hub-crumbs { display: flex; align-items: center; gap: 8px; color: ${C.sky}; flex: 1; min-width: 0; }
.hub-crumbs button { background: none; border: none; cursor: pointer; color: ${C.sky}; font: inherit; padding: 0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 220px; }
.hub-crumbs button:hover { color: ${C.steel}; }
.hub-crumbs .is-here { color: ${C.navy}; }

.hub-main { max-width: 1320px; margin: 0 auto; padding: 34px 32px 60px; }
/* A module supplies its own header, so the page gives it the full width
   and only enough padding to separate the navigation bar from the top. */
.hub-main-module { max-width: none; padding: 18px 24px 32px; }

/* Hero */
.hub-hero { margin-bottom: 28px; }
.hub-hero-title { font-size: 32px; font-weight: 600; color: ${C.navy}; letter-spacing: -0.02em; margin: 0; }
.hub-hero-title em { color: ${C.steel}; font-style: italic; }
.hub-hero-sub { font-size: 13px; color: ${C.steel}; margin: 8px 0 0; }

/* Cards */
.hub-card { background: ${C.white}; border: 1px solid ${C.ice}; border-radius: 3px; }
.hub-card-pad { padding: 22px 24px; }
.hub-card-head { display: flex; align-items: flex-start; gap: 20px; padding: 20px 24px 16px; border-bottom: 1px solid ${C.frost}; flex-wrap: wrap; }
.hub-card-title { font-size: 19px; font-weight: 600; color: ${C.navy}; margin: 0; }
.hub-card-note { font-size: 12.5px; color: ${C.steel}; margin-top: 4px; }
.hub-head-tools { margin-left: auto; display: flex; align-items: center; gap: 10px; }

/* KPIs */
.hub-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.hub-kpi-value { font-size: 30px; font-weight: 600; letter-spacing: -0.02em; line-height: 1; }
.hub-kpi-sub { font-size: 11.5px; color: ${C.steel}; margin-top: 10px; line-height: 1.45; }

/* Practice tiles — the only module tiles left, since these have no project to
   be reached through */
.hub-practice { display: grid; grid-template-columns: repeat(2, 1fr); gap: 14px; }
.hub-mod { text-align: left; background: ${C.white}; border: 1px solid ${C.ice}; border-radius: 3px;
  padding: 18px 20px 16px; cursor: pointer; display: flex; flex-direction: column; min-height: 148px;
  transition: border-color .15s, transform .15s, box-shadow .15s; }
.hub-mod:hover { border-color: ${C.steel}; transform: translateY(-2px); box-shadow: 0 6px 18px -12px ${C.navy}; }
.hub-mod:hover .hub-mod-arrow { color: ${C.steel}; transform: translateX(2px); }
.hub-mod-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.hub-mod-icon { width: 34px; height: 34px; display: grid; place-items: center; background: ${C.frost};
  color: ${C.steel}; border: 1px solid ${C.ice}; border-radius: 3px; }
.hub-mod-arrow { color: ${C.ice}; transition: transform .15s, color .15s; }
.hub-mod-name { font-size: 16px; font-weight: 600; color: ${C.navy}; margin-bottom: 5px; }
.hub-mod-tag { font-size: 12px; color: ${C.steel}; line-height: 1.45; }
.hub-wide-body { display: flex; align-items: flex-end; justify-content: space-between; gap: 20px; flex: 1; }
.hub-wide-figure { text-align: right; flex-shrink: 0; }
.hub-firm-stat { font-size: 26px; font-weight: 600; letter-spacing: -0.02em; line-height: 1; }
.hub-firm-detail { font-size: 11.5px; margin-top: 7px; }

/* Filters + search */
.hub-filters { display: flex; gap: 6px; flex-wrap: wrap; padding: 12px 24px; border-bottom: 1px solid ${C.frost}; }
.hub-chip { background: none; border: 1px solid ${C.ice}; border-radius: 2px; padding: 5px 11px;
  font-size: 11px; font-weight: 600; letter-spacing: .04em; color: ${C.steel}; cursor: pointer; transition: all .12s; }
.hub-chip:hover { border-color: ${C.sky}; }
.hub-chip.is-on { background: ${C.navy}; border-color: ${C.navy}; color: ${C.white}; }
.hub-search { display: flex; align-items: center; gap: 8px; border: 1px solid ${C.ice}; border-radius: 2px;
  padding: 7px 10px; background: ${C.white}; min-width: 280px; }
.hub-search:focus-within { border-color: ${C.steel}; }
.hub-search input { border: none; outline: none; font: inherit; font-size: 13px; color: ${C.ink}; flex: 1; background: none; }
.hub-search input::placeholder { color: ${C.sky}; }
.hub-search-clear { background: none; border: none; cursor: pointer; color: ${C.sky}; display: grid; place-items: center; padding: 0; }

/* Table */
.hub-table-scroll { overflow-x: auto; }
.hub-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.hub-table th { text-align: left; font-size: 9.5px; font-weight: 600; letter-spacing: .13em; text-transform: uppercase;
  color: ${C.sky}; padding: 12px 14px; border-bottom: 1px solid ${C.ice}; white-space: nowrap; }
.hub-table td { padding: 13px 14px; border-bottom: 1px solid ${C.frost}; vertical-align: middle; }
.hub-table tbody tr { cursor: pointer; transition: background .12s; }
.hub-table tbody tr:hover { background: ${C.frost}; }
.hub-table tbody tr:last-child td { border-bottom: none; }
.hub-file { color: ${C.steel}; font-size: 12px; }
.hub-row-name { display: block; font-weight: 600; color: ${C.navy}; }
.hub-row-sub { display: block; font-size: 11.5px; color: ${C.sky}; margin-top: 2px; }
.hub-muted { color: ${C.steel}; }

/* Module rail */
.hub-rail { display: flex; gap: 4px; }
.hub-rail-cell { width: 29px; height: 29px; display: grid; place-items: center; border: 1px solid ${C.ice};
  border-radius: 2px; background: ${C.white}; color: ${C.ice}; cursor: pointer; transition: all .12s; }
.hub-rail-cell.is-on { background: ${C.navy}; border-color: ${C.navy}; color: ${C.white}; }
.hub-rail-cell:hover { border-color: ${C.steel}; color: ${C.steel}; }
.hub-rail-cell.is-on:hover { background: ${C.steel}; border-color: ${C.steel}; color: ${C.white}; }

/* Pills */
.hub-pill { display: inline-flex; align-items: center; gap: 6px; border: 1px solid; border-radius: 2px;
  padding: 3px 9px; font-size: 10.5px; font-weight: 600; letter-spacing: .04em; white-space: nowrap; }
.hub-dot { width: 5px; height: 5px; border-radius: 50%; }

/* Buttons */
.hub-btn { display: inline-flex; align-items: center; gap: 7px; border-radius: 2px; padding: 8px 14px;
  font-size: 12px; font-weight: 600; letter-spacing: .03em; cursor: pointer; transition: all .13s; white-space: nowrap; }
.hub-btn:disabled { opacity: .45; cursor: not-allowed; }
.hub-btn-ghost { background: ${C.white}; border: 1px solid ${C.ice}; color: ${C.navy}; }
.hub-btn-ghost:hover:not(:disabled) { border-color: ${C.steel}; color: ${C.steel}; }
.hub-btn-solid { background: ${C.navy}; border: 1px solid ${C.navy}; color: ${C.white}; }
.hub-btn-solid:hover:not(:disabled) { background: ${C.indigo}; border-color: ${C.indigo}; }
.hub-btn-danger { background: ${C.white}; border: 1px solid ${C.ice}; color: ${STATUS.danger}; }
.hub-btn-danger:hover:not(:disabled) { border-color: ${STATUS.danger}; }
.hub-btn-danger-solid { background: ${STATUS.danger}; border: 1px solid ${STATUS.danger}; color: ${C.white}; }
.hub-icon-btn { background: none; border: none; cursor: pointer; color: ${C.steel}; display: grid; place-items: center; padding: 4px; }
.hub-icon-btn:hover { color: ${C.navy}; }

/* Empty */
.hub-empty { text-align: center; padding: 54px 40px; }
.hub-empty h3 { font-size: 21px; font-weight: 600; color: ${C.navy}; margin: 14px 0 6px; }
.hub-empty h3 em { color: ${C.steel}; font-style: italic; }
.hub-empty p { font-size: 13.5px; color: ${C.steel}; margin: 0 auto 20px; max-width: 380px; }
.hub-empty-actions { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }
.hub-empty-hint { font-size: 11.5px; color: ${C.sky}; max-width: 420px; margin: 18px auto 0; line-height: 1.6; }

/* Detail */
.hub-detail-nav { display: flex; align-items: center; gap: 8px; margin-bottom: 20px; flex-wrap: wrap; }
.hub-detail-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 20px;
  padding-bottom: 20px; border-bottom: 1px solid ${C.frost}; flex-wrap: wrap; }
.hub-detail-title { font-size: 30px; font-weight: 600; color: ${C.navy}; letter-spacing: -0.02em; margin: 0; }
.hub-detail-actions { display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
/* Pale green, the same tint the card takes on the BD board. */
.hub-pipeline-btn { display: inline-flex; align-items: center; gap: 6px; background: #eaf5ee;
  border: 1px solid #c3e2ce; color: #3a8a5f; font: inherit; font-size: 10px; font-weight: 600;
  letter-spacing: 0.07em; text-transform: uppercase; padding: 5px 10px; cursor: pointer;
  white-space: nowrap; transition: all 140ms ease; }
.hub-pipeline-btn:hover:not(:disabled) { background: #3a8a5f; color: ${C.white}; }
.hub-pipeline-btn:disabled { opacity: 0.6; cursor: wait; }
.hub-pipeline-tag { display: inline-flex; align-items: center; gap: 6px; background: #eaf5ee;
  border: 1px solid #c3e2ce; color: #3a8a5f; font-size: 10px; font-weight: 600;
  letter-spacing: 0.07em; text-transform: uppercase; padding: 5px 10px; white-space: nowrap; }
.hub-meta-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(210px, 1fr)); gap: 20px; padding: 22px 0; }
.hub-meta { display: flex; gap: 10px; align-items: flex-start; }
.hub-meta-value { font-size: 13.5px; color: ${C.navy}; line-height: 1.4; }
.hub-figures { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 20px;
  padding-top: 20px; border-top: 1px solid ${C.frost}; }
.hub-figure { font-size: 20px; font-weight: 600; color: ${C.navy}; letter-spacing: -0.01em; }

.hub-mod-cards { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; }
.hub-mod-card { display: flex; flex-direction: column; }
.hub-mod-card-top { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.hub-mod-card-name { font-size: 15.5px; font-weight: 600; color: ${C.navy}; margin-bottom: 6px; }
.hub-mod-card-stat { font-size: 12.5px; color: ${C.steel}; flex: 1; line-height: 1.45; }
.hub-state { font-size: 9.5px; font-weight: 600; letter-spacing: .12em; text-transform: uppercase; color: ${C.sky};
  border: 1px solid ${C.ice}; border-radius: 2px; padding: 3px 7px; }
.hub-state.is-on { color: ${STATUS.complete}; border-color: ${STATUS.complete}; }

/* Project type: one choice at a time. The selected colour is the pale neon
   green the Gantt track uses for a received project, so the two mean the same
   thing across the workspace. */
.hub-type-row { display: flex; gap: 8px; flex-wrap: wrap; }
.hub-type { background: ${C.white}; border: 1px solid ${C.ice}; color: ${C.steel};
  font: inherit; font-size: 10px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase;
  padding: 7px 12px; cursor: pointer; border-radius: 2px; transition: all 140ms ease; }
.hub-type:hover { border-color: ${C.steel}; color: ${C.navy}; }
/* Same footprint as a type button so the row keeps one rhythm. */
.hub-type-add { background: ${C.paper}; border: 1px dashed ${C.ice}; color: ${C.steel};
  font: inherit; font-size: 10px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase;
  padding: 7px 12px; cursor: pointer; border-radius: 2px; display: inline-flex; align-items: center;
  gap: 5px; transition: all 140ms ease; }
.hub-type-add:hover { border-color: ${C.steel}; color: ${C.navy}; background: ${C.frost}; }
.hub-type-input { border: 1px solid ${C.steel}; border-radius: 2px; padding: 6px 10px; font: inherit;
  font-size: 11px; letter-spacing: 0.04em; text-transform: uppercase; color: ${C.ink}; width: 150px; }
.hub-type-input:focus { outline: none; }
.hub-type.is-on { background: #d9ffb0; border-color: #7ce040; color: #2f4f12;
  box-shadow: inset 0 0 12px rgba(124, 224, 64, 0.55); }

.hub-notes { list-style: none; margin: 0 0 14px; padding: 0; display: flex; flex-direction: column; gap: 12px;
  max-height: 260px; overflow-y: auto; }
.hub-notes li { border-left: 2px solid ${C.ice}; padding-left: 12px; }
.hub-note-meta { font-size: 10px; font-weight: 600; letter-spacing: 0.1em; text-transform: uppercase; color: ${C.sky}; }
.hub-note-text { font-size: 13px; color: ${C.navy}; line-height: 1.55; margin-top: 3px; white-space: pre-wrap; }
.hub-notes-empty { font-size: 12.5px; color: ${C.sky}; margin: 0 0 14px; }
.hub-note-input { width: 100%; border: 1px solid ${C.ice}; border-radius: 2px; padding: 9px 11px;
  font: inherit; font-size: 13px; color: ${C.ink}; background: ${C.paper}; resize: vertical; }
.hub-note-input:focus { outline: none; border-color: ${C.steel}; }

.hub-planned-row { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 16px; }
.hub-planned { display: inline-flex; align-items: center; gap: 7px; font-size: 11.5px; font-weight: 600;
  color: ${C.sky}; border: 1px dashed ${C.ice}; border-radius: 2px; padding: 7px 11px; background: ${C.frost}; }

/* Module bar — persistent identity strip above whichever module is open */
.hub-modbar { display: flex; align-items: center; gap: 18px; margin-bottom: 20px; flex-wrap: wrap; }
.hub-modbar-title { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.hub-modbar-title .serif { font-size: 18px; font-weight: 600; color: ${C.navy}; line-height: 1.2; }
.hub-modbar-sub { font-size: 11.5px; color: ${C.steel}; }
.hub-modbar-rail { margin-left: auto; }
.hub-inline { font-family: ui-monospace, 'SF Mono', Menlo, monospace; font-size: 12px;
  background: ${C.frost}; border: 1px solid ${C.ice}; border-radius: 2px; padding: 1px 5px; color: ${C.indigo}; }

.hub-contract { max-width: 420px; margin: 0 auto; text-align: left; background: ${C.frost};
  border: 1px solid ${C.ice}; border-radius: 3px; padding: 16px 18px; }
.hub-contract code { display: block; white-space: pre; font-family: ui-monospace, 'SF Mono', Menlo, monospace;
  font-size: 11.5px; line-height: 1.7; color: ${C.indigo}; overflow-x: auto; }

/* Modal */
.hub-overlay { position: fixed; inset: 0; background: rgba(6,26,53,.42); backdrop-filter: blur(2px);
  display: grid; place-items: center; padding: 24px; z-index: 90; }
.hub-modal { background: ${C.white}; border: 1px solid ${C.ice}; border-radius: 3px; width: 100%; max-width: 620px;
  max-height: 88vh; display: flex; flex-direction: column; box-shadow: 0 24px 60px -20px rgba(6,26,53,.4); }
.hub-modal-head { display: flex; align-items: center; justify-content: space-between; padding: 20px 24px;
  border-bottom: 1px solid ${C.frost}; }
.hub-modal-head h2 { font-size: 20px; font-weight: 600; color: ${C.navy}; margin: 0; }
.hub-modal-head em { color: ${C.steel}; font-style: italic; }
.hub-modal-body { padding: 22px 24px; overflow-y: auto; }
.hub-modal-foot { display: flex; justify-content: flex-end; gap: 10px; padding: 16px 24px;
  border-top: 1px solid ${C.frost}; background: ${C.paper}; }
.hub-form { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.hub-input { width: 100%; border: 1px solid ${C.ice}; border-radius: 2px; padding: 9px 11px; font: inherit;
  font-size: 13px; color: ${C.ink}; background: ${C.white}; }
.hub-input:focus { outline: none; border-color: ${C.steel}; }
.hub-input::placeholder { color: ${C.sky}; }
.hub-warn { display: flex; gap: 12px; align-items: flex-start; font-size: 13.5px; color: ${C.navy}; line-height: 1.55; }

.hub-reset-list { margin: 0 0 16px; padding-left: 18px; font-size: 12.5px; color: ${C.steel}; line-height: 1.7; }
.hub-reset-opt { display: flex; gap: 10px; align-items: flex-start; padding: 12px 14px; background: ${C.paper};
  border: 1px solid ${C.ice}; border-radius: 2px; cursor: pointer; }
.hub-reset-opt input { margin-top: 2px; accent-color: ${C.navy}; cursor: pointer; }
.hub-reset-opt strong { display: block; font-size: 13px; color: ${C.navy}; font-weight: 600; }
.hub-reset-opt em { display: block; font-size: 11.5px; color: ${C.steel}; font-style: normal; margin-top: 3px; line-height: 1.5; }
.hub-reset-link { background: none; border: none; cursor: pointer; font: inherit; font-size: 10px;
  font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; color: ${C.sky}; padding: 0; }
.hub-reset-link:hover { color: ${STATUS.danger}; }
.hub-safe-link:hover { color: ${C.steel}; }
.hub-notice { position: fixed; bottom: 20px; left: 50%; transform: translateX(-50%);
  display: flex; align-items: center; gap: 12px; background: ${C.white}; border: 1px solid ${C.ice};
  border-left: 3px solid ${STATUS.complete}; border-radius: 2px; padding: 12px 14px 12px 16px;
  font-size: 13px; color: ${C.navy}; box-shadow: 0 8px 24px -14px ${C.navy}; z-index: 95; }
.hub-notice-bad { border-left-color: ${STATUS.danger}; }

.hub-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 48px;
  padding-top: 22px; border-top: 1px solid ${C.ice}; color: ${C.steel}; }

/* Responsive */
@media (max-width: 1080px) {
  .hub-kpis, .hub-mod-cards { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 720px) {
  .hub-topbar-inner, .hub-main { padding-left: 18px; padding-right: 18px; }
  .hub-crumbs { display: none; }
  .hub-kpis, .hub-mod-cards, .hub-practice { grid-template-columns: 1fr; }
  .hub-wide-body { flex-direction: column; align-items: flex-start; gap: 14px; }
  .hub-wide-figure { text-align: left; }
  .hub-hero-title { font-size: 25px; }
  .hub-head-tools { width: 100%; margin-left: 0; }
  .hub-search { min-width: 0; flex: 1; }
  .hub-form { grid-template-columns: 1fr; }
  .hub-form > div { grid-column: span 1 !important; }
}
@media (prefers-reduced-motion: reduce) {
  .beacon-hub * { transition: none !important; }
}
`;
